public PDColor(COSArray array, PDColorSpace colorSpace)
{
    if (array.size() > 0 && array.get(array.size() - 1) instanceof COSName)
    {
        // color components (optional), for the color of an uncoloured tiling pattern
        components = new float[array.size() - 1];
        initComponents(array);

        // pattern name (required)
        COSBase base = array.get(array.size() - 1);
        if (base instanceof COSName)
        {
            patternName = (COSName) base;
        }
        else
        {
            LOG.warn("pattern name in " + array + " isn't a name, ignored");
            patternName = COSName.getPDFName("Unknown");
        }
    }
    else
    {
        // color components only
        components = new float[array.size()];
        initComponents(array);
        patternName = null;
    }
    this.colorSpace = colorSpace;
}

public void setItem(COSName key, COSBase value)
{
    if (value == null)
    {
        removeItem(key);
    }
    else
    {
        // wrap indirect objects
        if ((value instanceof COSDictionary || value instanceof COSArray) && !value.isDirect()
                && value.getKey() != null)
        {
            COSObject cosObject = new COSObject(value, value.getKey());
            items.put(key, cosObject);
            getUpdateState().update(cosObject);
        }
        else
        {
            items.put(key, value);
            getUpdateState().update(value);
        }
    }
}

public COSParser(RandomAccessRead source, String password, InputStream keyStore,
        String keyAlias) throws IOException
{
    this(source, password, keyStore, keyAlias, null);
}

public COSParser(RandomAccessRead source, String password, InputStream keyStore,
        String keyAlias, StreamCacheCreateFunction streamCacheCreateFunction) throws IOException
{
    super(source);
    this.password = password;
    this.keyAlias = keyAlias;
    fileLen = source.length();
    keyStoreInputStream = keyStore;
    init(streamCacheCreateFunction);
}

public COSBase getObject()
{
    if (!isDereferenced && parser != null)
    {
        try
        {
            // mark as dereferenced to avoid endless recursions
            isDereferenced = true;
            baseObject = parser.dereferenceCOSObject(this);
            getUpdateState().dereferenceChild(baseObject);
        }
        catch (IOException e)
        {
            LOG.error("Can't dereference " + this, e);
        }
        finally
        {
            parser = null;
        }
    }
    return baseObject;
}

public String getNameAsString(COSName key)
{
    String retval = null;
    COSBase name = getDictionaryObject(key);
    if (name instanceof COSName)
    {
        retval = ((COSName) name).getName();
    }
    else if (name instanceof COSString)
    {
        retval = ((COSString) name).getString();
    }
    return retval;
}

public COSStream createCOSStream(COSDictionary dictionary, long startPosition,
        long streamLength) throws IOException
{
    COSStream stream = new COSStream(streamCache,
            parser.createRandomAccessReadView(startPosition, streamLength));
    dictionary.forEach(stream::setItem);
    stream.setKey(dictionary.getKey());
    return stream;
}

public PDFObjectStreamParser(COSStream stream, COSDocument document) throws IOException
{
    super(stream.createView());
    this.document = document;
    // get mandatory number of objects
    numberOfObjects = stream.getInt(COSName.N);
    if (numberOfObjects == -1)
    {
        throw new IOException("/N entry missing in object stream");
    }
    if (numberOfObjects < 0)
    {
        throw new IOException("Illegal /N entry in object stream: " + numberOfObjects);
    }
    // get mandatory stream offset of the first object
    firstObject = stream.getInt(COSName.FIRST);
    if (firstObject == -1)
    {
        throw new IOException("/First entry missing in object stream");
    }
    if (firstObject < 0)
    {
        throw new IOException("Illegal /First entry in object stream: " + firstObject);
    }
}

public Map<COSObjectKey, COSBase> parseAllObjects() throws IOException
{
    Map<COSObjectKey, COSBase> allObjects = new HashMap<>();
    try
    {
        Map<Integer, Long> objectNumbers = privateReadObjectOffsets();
        // count the number of object numbers eliminating double entries
        long numberOfObjNumbers = objectNumbers.values().stream().distinct().count();
        // the usage of the index should be restricted to cases where more than one
        // object use the same object number.
        // there are malformed pdfs in the wild which would lead to false results if
        // pdfbox always relies on the index if available. In most cases the object number
        // is sufficient to choose the correct object
        boolean indexNeeded = objectNumbers.size() > numberOfObjNumbers;
        long currentPosition = source.getPosition();
        if (firstObject > 0 && currentPosition < firstObject)
        {
            source.skip(firstObject - (int) currentPosition);
        }
        int index = 0;
        for (Entry<Integer, Long> entry : objectNumbers.entrySet())
        {
            COSObjectKey objectKey = getObjectKey(entry.getValue(), 0);
            // skip object if the index doesn't match
            if (indexNeeded && objectKey.getStreamIndex() > -1
                    && objectKey.getStreamIndex() != index)
            {
                index++;
                continue;
            }
            int finalPosition = firstObject + entry.getKey();
            currentPosition = source.getPosition();
            if (finalPosition > 0 && currentPosition < finalPosition)
            {
                // jump to the offset of the object to be parsed
                source.skip(finalPosition - (int) currentPosition);
            }
            COSBase streamObject = parseDirObject();
            if (streamObject != null)
            {
                streamObject.setDirect(false);
            }
            allObjects.put(objectKey, streamObject);
            index++;
        }
    }
    finally
    {
        source.close();
        document = null;
    }
    return allObjects;
}

public void filter(byte[] b, int off, int len)
{
    if (pos == 0 && len > 10)
    {
        // PDFBOX-2120 Don't filter if ASCII, i.e. keep a final CR LF or LF
        mustFilter = false;
        for (int i = 0; i < 10; ++i)
        {
            // Heuristic approach, taken from PDFStreamParser, PDFBOX-1164
            if ((b[i] < 0x09) || ((b[i] > 0x0a) && (b[i] < 0x20) && (b[i] != 0x0d)))
            {
                // control character or > 0x7f -> we have binary data
                mustFilter = true;
                break;
            }
        }
    }
    if (mustFilter)
    {
        // first write what we kept last time
        if (hasCR)
        {
            // previous buffer ended with CR
            hasCR = false;
            if (!hasLF && len == 1 && b[off] == '\n')
            {
                // actual buffer contains only LF so it will be the last one
                // => we're done
                // reset hasCR done too to avoid CR getting written in the flush
                return;
            }
            length++;
        }
        if (hasLF)
        {
            length++;
            hasLF = false;
        }
        // don't write CR, LF, or CR LF if at the end of the buffer
        if (len > 0)
        {
            if (b[off + len - 1] == '\r')
            {
                hasCR = true;
                --len;
            }
            else if (b[off + len - 1] == '\n')
            {
                hasLF = true;
                --len;
                if (len > 0 && b[off + len - 1] == '\r')
                {
                    hasCR = true;
                    --len;
                }
            }
        }
    }
    length += len;
    pos += len;
}

public PDFunctionType2(COSBase function)
{
    super(function);

    COSArray cosArray0 = getCOSObject().getCOSArray(COSName.C0);
    if (cosArray0 != null)
    {
        c0 = cosArray0;
    }
    else
    {
        c0 = new COSArray();
    }
    if (c0.size() == 0)
    {
        c0.add(new COSFloat(0));
    }

    COSArray cosArray1 = getCOSObject().getCOSArray(COSName.C1);
    if (cosArray1 != null)
    {
        c1 = cosArray1;
    }
    else
    {
        c1 = new COSArray();
    }
    if (c1.size() == 0)
    {
        c1.add(new COSFloat(1));
    }

    exponent = getCOSObject().getFloat(COSName.N);
}

public PDFunction( COSBase function )
{
    if (function instanceof COSStream)
    {
        functionStream = new PDStream( (COSStream)function );
        functionStream.getCOSObject().setItem( COSName.TYPE, COSName.FUNCTION );
    }
    else if (function instanceof COSDictionary)
    {
        functionDictionary = (COSDictionary)function;
    }
}

public void setFlag(COSName field, int bitFlag, boolean value)
{
    int currentFlags = getInt(field, 0);
    if (value)
    {
        currentFlags = currentFlags | bitFlag;
    }
    else
    {
        currentFlags &= ~bitFlag;
    }
    setInt(field, currentFlags);
}

public List<String> getExportValues()
{
    COSBase value = getInheritableAttribute(COSName.OPT);

    if (value instanceof COSString)
    {
        return Collections.singletonList(((COSString) value).getString());
    }
    else if (value instanceof COSArray)
    {
        return ((COSArray) value).toCOSStringStringList();
    }
    return Collections.emptyList();
}

public Set<String> getOnValues()
{
    // we need a set as the field can appear multiple times
    Set<String> onValues = new LinkedHashSet<>();
    List<String> exportValues = getExportValues();
    if (!exportValues.isEmpty())
    {
        onValues.addAll(exportValues);
        return onValues;
    }

    List<PDAnnotationWidget> widgets = this.getWidgets();
    for (PDAnnotationWidget widget : widgets)
    {
        onValues.add(getOnValueForWidget(widget));
    }        
    return onValues;
}

public String getValue()
{
    COSBase value = getInheritableAttribute(COSName.V);
    if (value instanceof COSName)
    {
        String stringValue = ((COSName)value).getName();
        List<String> exportValues = getExportValues();
        if (!exportValues.isEmpty())
        {
            try
            {
                int idx = Integer.parseInt(stringValue, 10);
                if (idx >= 0 && idx < exportValues.size())
                {
                    return exportValues.get(idx);
                }
            }
            catch (NumberFormatException nfe)
            {
                return stringValue;
            }
        }
        return stringValue;
    }
    else
    {
        // Off is the default value if there is nothing else set.
        // See PDF Spec.
        return "Off";
    }
}

public COSBase getObject( int index )
{
    COSBase obj = objects.get( index );
    if( obj instanceof COSObject )
    {
        obj = ((COSObject)obj).getObject();
    }
    if (obj instanceof COSNull)
    {
        obj = null;
    }
    return obj;
}

public PDType1Font(FontName baseFont)
{
    super(baseFont);

    dict.setItem(COSName.SUBTYPE, COSName.TYPE1);
    dict.setName(COSName.BASE_FONT, baseFont.getName());
    switch (baseFont)
    {
    case ZAPF_DINGBATS:
        encoding = ZapfDingbatsEncoding.INSTANCE;
        break;
    case SYMBOL:
        encoding = SymbolEncoding.INSTANCE;
        break;
    default:
        encoding = WinAnsiEncoding.INSTANCE;
        dict.setItem(COSName.ENCODING, COSName.WIN_ANSI_ENCODING);
        break;
    }

    // todo: could load the PFB font here if we wanted to support Standard 14 embedding
    type1font = null;
    FontMapping<FontBoxFont> mapping = FontMappers.instance()
                                                  .getFontBoxFont(getBaseFont(),
                                                                  getFontDescriptor());
    genericFont = mapping.getFont();

    if (mapping.isFallback())
    {
        String fontName;
        try
        {
            fontName = genericFont.getName();
        }
        catch (IOException e)
        {
            LOG.debug("Couldn't get font name - setting to '?'", e);
            fontName = "?";
        }
        LOG.warn("Using fallback font " + fontName + " for base font " + getBaseFont());
    }
    isEmbedded = false;
    isDamaged = false;
    fontMatrixTransform = new AffineTransform();
}

public PDType1Font(COSDictionary fontDictionary) throws IOException
{
    super(fontDictionary);

    PDFontDescriptor fd = getFontDescriptor();
    Type1Font t1 = null;
    boolean fontIsDamaged = false;
    if (fd != null)
    {
        // a Type1 font may contain a Type1C font
        PDStream fontFile3 = fd.getFontFile3();
        if (fontFile3 != null)
        {
            LOG.warn("/FontFile3 for Type1 font not supported");
        }

        // or it may contain a PFB
        PDStream fontFile = fd.getFontFile();
        if (fontFile != null)
        {
            try
            {
                COSStream stream = fontFile.getCOSObject();
                int length1 = stream.getInt(COSName.LENGTH1);
                int length2 = stream.getInt(COSName.LENGTH2);

                // repair Length1 and Length2 if necessary
                byte[] bytes = fontFile.toByteArray();
                if (bytes.length == 0)
                {
                    throw new IOException("Font data unavailable");
                }
                length1 = repairLength1(bytes, length1);
                length2 = repairLength2(bytes, length1, length2);

                if ((bytes[0] & 0xff) == PFB_START_MARKER)
                {
                    // some bad files embed the entire PFB, see PDFBOX-2607
                    t1 = Type1Font.createWithPFB(bytes);
                }
                else
                {
                    // the PFB embedded as two segments back-to-back
                    if (length1 < 0 || length1 > length1 + length2)
                    {
                        throw new IOException("Invalid length data, actual length: " +
                                bytes.length + ", /Length1: " + length1 + ", /Length2: " + length2);
                    }
                    byte[] segment1 = Arrays.copyOfRange(bytes, 0, length1);
                    byte[] segment2 = Arrays.copyOfRange(bytes, length1, length1 + length2);

                    // empty streams are simply ignored
                    if (length1 > 0 && length2 > 0)
                    {
                        t1 = Type1Font.createWithSegments(segment1, segment2);
                    }
                }
            }
            catch (DamagedFontException e)
            {
                LOG.warn("Can't read damaged embedded Type1 font " + fd.getFontName(), e);
                fontIsDamaged = true;
            }
            catch (IOException e)
            {
                LOG.error("Can't read the embedded Type1 font " + fd.getFontName(), e);
                fontIsDamaged = true;
            }
        }
    }
    isEmbedded = t1 != null;
    isDamaged = fontIsDamaged;
    type1font = t1;

    // find a generic font to use for rendering, could be a .pfb, but might be a .ttf
    if (type1font != null)
    {
        genericFont = type1font;
    }
    else
    {
        FontMapping<FontBoxFont> mapping = FontMappers.instance()
                                                      .getFontBoxFont(getBaseFont(), fd);
        genericFont = mapping.getFont();

        if (mapping.isFallback())
        {
            LOG.warn("Using fallback font " + genericFont.getName() + " for " + getBaseFont());
        }
    }
    readEncoding();
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

public float getAverageFontWidth()
{
    float average;
    if (Float.compare(avgFontWidth, 0.0f) != 0)
    {
        average = avgFontWidth;
    }
    else
    {
        float totalWidth = 0.0f;
        float characterCount = 0.0f;
        COSArray widths = dict.getCOSArray(COSName.WIDTHS);
        if (widths != null)
        {
            for (int i = 0; i < widths.size(); i++)
            {
                COSBase base = widths.getObject(i);
                if (base instanceof COSNumber)
                {
                    COSNumber fontWidth = (COSNumber) base;
                    float floatValue = fontWidth.floatValue();
                    if (floatValue > 0)
                    {
                        totalWidth += floatValue;
                        characterCount += 1;
                    }
                }
            }
        }

        if (totalWidth > 0)
        {
            average = totalWidth / characterCount;
        }
        else
        {
            average = 0;
        }
        avgFontWidth = average;
    }
    return average;
}

