public COSArray getBorder()
{
    COSArray border = getCOSObject().getCOSArray(COSName.BORDER);
    if (border != null)
    {
        if (border.size() < 3)
        {
            // create a copy to avoid altering the PDF
            COSArray newBorder = new COSArray();
            newBorder.addAll(border);
            border = newBorder;
            // Adobe Reader behaves as if missing elements are 0.
            while (border.size() < 3)
            {
                border.add(COSInteger.ZERO);
            }
        }
    }
    else
    {
        border = new COSArray();
        border.add(COSInteger.ZERO);
        border.add(COSInteger.ZERO);
        border.add(COSInteger.ONE);
    }
    return border;
}

public PDAppearanceStream getNormalAppearanceStream()
{
    PDAppearanceDictionary appearanceDict = getAppearance();
    if (appearanceDict == null)
    {
        return null;
    }

    PDAppearanceEntry normalAppearance = appearanceDict.getNormalAppearance();
    if (normalAppearance == null)
    {
        return null;
    }

    if (normalAppearance.isSubDictionary())
    {
        COSName state = getAppearanceState();
        return normalAppearance.getSubDictionary().get(state);
    }
    else
    {
        return normalAppearance.getAppearanceStream();
    }
}

public DecodeResult decode(InputStream encoded, OutputStream decoded, COSDictionary parameters,
                           int index, DecodeOptions options) throws IOException
{
    return decode(encoded, decoded, parameters, index);
}

public COSBase getDictionaryObject(COSName key)
{
    COSBase retval = items.get(key);
    if (retval instanceof COSObject)
    {
        retval = ((COSObject) retval).getObject();
    }
    if (retval instanceof COSNull)
    {
        retval = null;
    }
    return retval;
}

public int indexOfObject(COSBase object)
{
    for (int i = 0; i < this.size(); i++)
    {
        COSBase item = this.get(i);
        if (item == null)
        {
            if (item == object)
            {
                return i;
            }
        }
        else if (item.equals(object))
        {
            return i;
        }
        else if (item instanceof COSObject && ((COSObject) item).getObject() != null &&
                  ((COSObject) item).getObject().equals(object))
        {
            return i;
        }
    }
    return -1;
}

public boolean removeObject(COSBase o)
{
    boolean removed = this.remove(o);
    if (!removed)
    {
        for (int i = 0; i < this.size(); i++)
        {
            COSBase entry = this.get(i);
            if (entry instanceof COSObject)
            {
                COSObject objEntry = (COSObject) entry;
                if (objEntry.getObject().equals(o))
                {
                    return this.remove(entry);
                }
            }
        }
    }
    return removed;
}

public List<PDAnnotationWidget> getWidgets()
{
    List<PDAnnotationWidget> widgets = new ArrayList<>();
    COSArray kids = getCOSObject().getCOSArray(COSName.KIDS);
    if (kids == null)
    {
        // the field itself is a widget
        widgets.add(new PDAnnotationWidget(getCOSObject()));
    }
    else if (kids.size() > 0)
    {
        // there are multiple widgets
        for (int i = 0; i < kids.size(); i++)
        {
            COSBase kid = kids.getObject(i);
            if (kid instanceof COSDictionary)
            {
                widgets.add(new PDAnnotationWidget((COSDictionary)kid));
            }
        }
    }
    return widgets;
}

public boolean equals(Object obj)
{
    if (this == obj)
    {
        return true;
    }
    if (obj == null)
    {
        return false;
    }
    if (getClass() != obj.getClass())
    {
        if (obj instanceof Point2D)
        {
            // hitting this branch means that the warning on top of the class wasn't read
            LOG.error("IntPoint should not be used together with its base class");
        }
        return false;
    }
    final IntPoint other = (IntPoint) obj;
    return this.x == other.x && this.y == other.y;
}

public FDFAnnotationInk(Element element) throws IOException
{
    super(element);
    annot.setName(COSName.SUBTYPE, SUBTYPE);

    XPath xpath = XPathFactory.newInstance().newXPath();
    try
    {
        NodeList gestures = (NodeList) xpath.evaluate("inklist/gesture", element,
                XPathConstants.NODESET);
        if (gestures.getLength() == 0)
        {
            throw new IOException("Error: missing element 'gesture'");
        }
        List<float[]> inklist = new ArrayList<>();
        for (int i = 0; i < gestures.getLength(); i++)
        {
            Node node = gestures.item(i);
            if (node instanceof Element)
            {
                String gesture = node.getFirstChild().getNodeValue();
                String[] gestureValues = gesture.split("[,;]");
                float[] values = new float[gestureValues.length];
                for (int j = 0; j < gestureValues.length; j++)
                {
                    values[j] = Float.parseFloat(gestureValues[j]);
                }
                inklist.add(values);
            }
        }
        setInkList(inklist);
    }
    catch (XPathExpressionException e)
    {
        LOG.debug("Error while evaluating XPath expression for inklist gestures", e);
    }
}

public FDFAnnotation(Element element) throws IOException
{
    this();

    String page = element.getAttribute("page");
    if (page == null || page.isEmpty())
    {
        throw new IOException("Error: missing required attribute 'page'");
    }
    setPage(Integer.parseInt(page));

    String color = element.getAttribute("color");
    if (color != null && color.length() == 7 && color.charAt(0) == '#')
    {
        int colorValue = Integer.parseInt(color.substring(1, 7), 16);
        setColor(new Color(colorValue));
    }

    setDate(element.getAttribute("date"));

    String flags = element.getAttribute("flags");
    if (flags != null)
    {
        String[] flagTokens = flags.split(",");
        for (String flagToken : flagTokens)
        {
            switch (flagToken)
            {
                case "invisible":
                    setInvisible(true);
                    break;
                case "hidden":
                    setHidden(true);
                    break;
                case "print":
                    setPrinted(true);
                    break;
                case "nozoom":
                    setNoZoom(true);
                    break;
                case "norotate":
                    setNoRotate(true);
                    break;
                case "noview":
                    setNoView(true);
                    break;
                case "readonly":
                    setReadOnly(true);
                    break;
                case "locked":
                    setLocked(true);
                    break;
                case "togglenoview":
                    setToggleNoView(true);
                    break;
                default:
                    break;
            }
        }
    }

    setName(element.getAttribute("name"));

    String rect = element.getAttribute("rect");
    if (rect == null)
    {
        throw new IOException("Error: missing attribute 'rect'");
    }
    String[] rectValues = rect.split(",");
    if (rectValues.length != 4)
    {
        throw new IOException("Error: wrong amount of numbers in attribute 'rect'");
    }
    float[] values = new float[4];
    for (int i = 0; i < 4; i++)
    {
        values[i] = Float.parseFloat(rectValues[i]);
    }
    COSArray array = new COSArray();
    array.setFloatArray(values);
    setRectangle(new PDRectangle(array));

    setTitle(element.getAttribute("title"));

    /*
     * Set the markup annotation attributes
     */
    setCreationDate(DateConverter.toCalendar(element.getAttribute("creationdate")));
    String opac = element.getAttribute("opacity");
    if (opac != null && !opac.isEmpty())
    {
        setOpacity(Float.parseFloat(opac));
    }
    setSubject(element.getAttribute("subject"));

    String intent = element.getAttribute("intent");
    if (intent.isEmpty())
    {
        // not conforming to spec, but qoppa produces it and Adobe accepts it
        intent = element.getAttribute("IT");
    }
    if (!intent.isEmpty())
    {
        setIntent(intent);
    }

    XPath xpath = XPathFactory.newInstance().newXPath();
    try
    {
        setContents(xpath.evaluate("contents[1]", element));
    }
    catch (XPathExpressionException e)
    {
        LOG.debug("Error while evaluating XPath expression for richtext contents", e);
    }

    try
    {
        Node richContents = (Node) xpath.evaluate("contents-richtext[1]", element,
                XPathConstants.NODE);
        if (richContents != null)
        {
            setRichContents(richContentsToString(richContents, true));
            setContents(richContents.getTextContent().trim());
        }
    }
    catch (XPathExpressionException e)
    {
        LOG.debug("Error while evaluating XPath expression for richtext contents", e);
    }

    PDBorderStyleDictionary borderStyle = new PDBorderStyleDictionary();
    String width = element.getAttribute("width");
    if (width != null && !width.isEmpty())
    {
        borderStyle.setWidth(Float.parseFloat(width));
    }
    if (borderStyle.getWidth() > 0)
    {
        String style = element.getAttribute("style");
        if (style != null && !style.isEmpty())
        {
            switch (style)
            {
                case "dash":
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_DASHED);
                    break;
                case "bevelled":
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_BEVELED);
                    break;
                case "inset":
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_INSET);
                    break;
                case "underline":
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_SOLID);
                    break;
                case "cloudy":
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_SOLID);
                    PDBorderEffectDictionary borderEffect = new PDBorderEffectDictionary();
                    borderEffect.setStyle(PDBorderEffectDictionary.STYLE_CLOUDY);
                    String intensity = element.getAttribute("intensity");
                    if (intensity != null && !intensity.isEmpty())
                    {
                        borderEffect.setIntensity(Float.parseFloat(element
                                .getAttribute("intensity")));
                    }
                    setBorderEffect(borderEffect);
                    break;
                default:
                    borderStyle.setStyle(PDBorderStyleDictionary.STYLE_SOLID);
                    break;
            }
        }
        String dashes = element.getAttribute("dashes");
        if (dashes != null && !dashes.isEmpty())
        {
            String[] dashesValues = dashes.split(",");
            COSArray dashPattern = new COSArray();
            for (String dashesValue : dashesValues)
            {
                dashPattern.add(COSNumber.get(dashesValue));
            }
            borderStyle.setDashStyle(dashPattern);
        }
        setBorderStyle(borderStyle);
    }
}

public String toString()
{
    StringBuilder sb = new StringBuilder("Process{");
    try
    {
        sb.append(getColorSpace());
        for (String component : getComponents())
        {
            sb.append(" \"");
            sb.append(component);
            sb.append('\"');
        }
    }
    catch (IOException e)
    {
        LOG.debug("Couldn't get the colorants information - returning 'ERROR' instead'", e);
        sb.append("ERROR");
    }
    sb.append('}');
    return sb.toString();
}

public PDCIDFontType2(COSDictionary fontDictionary, PDType0Font parent, TrueTypeFont trueTypeFont) throws IOException
{
    super(fontDictionary, parent);

    PDFontDescriptor fd = getFontDescriptor();
    if (trueTypeFont != null)
    {
        ttf = trueTypeFont;
        otf = trueTypeFont instanceof OpenTypeFont
                && ((OpenTypeFont) trueTypeFont).isSupportedOTF() ? (OpenTypeFont) trueTypeFont
                        : null;
        isEmbedded = true;
        isDamaged = false;
    }
    else
    {
        boolean fontIsDamaged = false;
        TrueTypeFont ttfFont = null;

        PDStream stream = null;
        if (fd != null)
        {
            stream = fd.getFontFile2();
            if (stream == null)
            {
                stream = fd.getFontFile3();
            }
            if (stream == null)
            {
                // Acrobat looks in FontFile too, even though it is not in the spec, see PDFBOX-2599
                stream = fd.getFontFile();
            }
        }
        if (stream != null)
        {
            try
            {
                // embedded OTF or TTF
                RandomAccessRead view = stream.getCOSObject().createView();
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            }
            catch (IOException e)
            {
                fontIsDamaged = true;
                LOG.warn("Could not read embedded OTF for font " + getBaseFont(), e);
            }
            if (ttfFont instanceof OpenTypeFont && !((OpenTypeFont) ttfFont).isSupportedOTF())
            {
                // the OpenType font contains CFF2 outlines which are not supported yet
                ttfFont = null;
                fontIsDamaged = true;
                LOG.warn("Found an OpenType font using CFF2 outlines which are not supported "
                        + fd.getFontName());
            }

        }
        isEmbedded = ttfFont != null;
        isDamaged = fontIsDamaged;

        if (ttfFont == null)
        {
            ttfFont = findFontOrSubstitute();
        }
        otf = ttfFont instanceof OpenTypeFont && ((OpenTypeFont) ttfFont).isSupportedOTF()
                ? (OpenTypeFont) ttfFont : null;
        ttf = ttfFont;
    }
    cmap = ttf.getUnicodeCmapLookup(false);
    cid2gid = readCIDToGIDMap();
}

public RandomAccessRead createView() throws IOException
{
    List<Filter> filterList = getFilterList();
    if (filterList.isEmpty())
    {
        if (randomAccess == null && randomAccessReadView != null)
        {
            return new RandomAccessReadView(randomAccessReadView, 0,
                    randomAccessReadView.length());
        }
        else
        {
            return new RandomAccessReadBuffer(createRawInputStream());
        }
    }
    return Filter.decode(createRawInputStream(), filterList, this, DecodeOptions.DEFAULT, null);
}

public String getString()
{
    // text string - BOM indicates Unicode
    if (bytes.length >= 2)
    {
        if ((bytes[0] & 0xff) == 0xFE && (bytes[1] & 0xff) == 0xFF)
        {
            // UTF-16BE
            return new String(bytes, 2, bytes.length - 2, StandardCharsets.UTF_16BE);
        }
        else if ((bytes[0] & 0xff) == 0xFF && (bytes[1] & 0xff) == 0xFE)
        {
            // UTF-16LE - not in the PDF spec!
            return new String(bytes, 2, bytes.length - 2, StandardCharsets.UTF_16LE);
        }
    }

    // otherwise use PDFDocEncoding
    return PDFDocEncoding.toString(bytes);
}

public FDFDictionary(Element fdfXML)
{
    this();
    NodeList nodeList = fdfXML.getChildNodes();
    for (int i = 0; i < nodeList.getLength(); i++)
    {
        Node node = nodeList.item(i);
        if (node instanceof Element)
        {
            Element child = (Element) node;
            switch (child.getTagName())
            {
                case "f":
                    PDSimpleFileSpecification fs = new PDSimpleFileSpecification();
                    fs.setFile(child.getAttribute("href"));
                    setFile(fs);
                    break;
                case "ids":
                    COSArray ids = new COSArray();
                    String original = child.getAttribute("original");
                    String modified = child.getAttribute("modified");
                    try
                    {
                        ids.add(COSString.parseHex(original));
                    }
                    catch (IOException e)
                    {
                        LOG.warn("Error parsing ID entry for attribute 'original' [" + original +
                                "]. ID entry ignored.", e);
                    }
                    try
                    {
                        ids.add(COSString.parseHex(modified));
                    }
                    catch (IOException e)
                    {
                        LOG.warn("Error parsing ID entry for attribute 'modified' [" + modified +
                                "]. ID entry ignored.", e);
                    }
                    setID(ids);
                    break;
                case "fields":
                    NodeList fields = child.getChildNodes();
                    List<FDFField> fieldList = new ArrayList<>();
                    for (int f = 0; f < fields.getLength(); f++)
                    {
                        Node currentNode = fields.item(f);
                        if (currentNode instanceof Element
                                && ((Element) currentNode).getTagName().equals("field"))
                        {
                            try
                            {
                                fieldList.add(new FDFField((Element) fields.item(f)));
                            }
                            catch (IOException e)
                            {
                                LOG.warn("Error parsing field entry [" + currentNode.getNodeValue() +
                                        "]. Field ignored.", e);
                            }
                        }
                    }
                    setFields(fieldList);
                    break;
                case "annots":
                    NodeList annots = child.getChildNodes();
                    List<FDFAnnotation> annotList = new ArrayList<>();
                    for (int j = 0; j < annots.getLength(); j++)
                    {
                        Node annotNode = annots.item(j);
                        if (annotNode instanceof Element)
                        {
                            // the node name defines the annotation type
                            Element annot = (Element) annotNode;
                            String annotationName = annot.getNodeName();
                            try
                            {
                                switch (annotationName)
                                {
                                    case "text":
                                        annotList.add(new FDFAnnotationText(annot));
                                        break;
                                    case "caret":
                                        annotList.add(new FDFAnnotationCaret(annot));
                                        break;
                                    case "freetext":
                                        annotList.add(new FDFAnnotationFreeText(annot));
                                        break;
                                    case "fileattachment":
                                        annotList.add(new FDFAnnotationFileAttachment(annot));
                                        break;
                                    case "highlight":
                                        annotList.add(new FDFAnnotationHighlight(annot));
                                        break;
                                    case "ink":
                                        annotList.add(new FDFAnnotationInk(annot));
                                        break;
                                    case "line":
                                        annotList.add(new FDFAnnotationLine(annot));
                                        break;
                                    case "link":
                                        annotList.add(new FDFAnnotationLink(annot));
                                        break;
                                    case "circle":
                                        annotList.add(new FDFAnnotationCircle(annot));
                                        break;
                                    case "square":
                                        annotList.add(new FDFAnnotationSquare(annot));
                                        break;
                                    case "polygon":
                                        annotList.add(new FDFAnnotationPolygon(annot));
                                        break;
                                    case "polyline":
                                        annotList.add(new FDFAnnotationPolyline(annot));
                                        break;
                                    case "sound":
                                        annotList.add(new FDFAnnotationSound(annot));
                                        break;
                                    case "squiggly":
                                        annotList.add(new FDFAnnotationSquiggly(annot));
                                        break;
                                    case "stamp":
                                        annotList.add(new FDFAnnotationStamp(annot));
                                        break;
                                    case "strikeout":
                                        annotList.add(new FDFAnnotationStrikeOut(annot));
                                        break;
                                    case "underline":
                                        annotList.add(new FDFAnnotationUnderline(annot));
                                        break;
                                    default:
                                        LOG.warn("Unknown or unsupported annotation type '" +
                                                annotationName + "'");
                                        break;
                                }
                            }
                            catch (IOException e)
                            {
                                LOG.warn("Error parsing annotation information [" +
                                        annot.getNodeValue() + "]. Annotation ignored", e);
                            }
                        }
                    }
                    setAnnotations(annotList);
                    break;
                default:
                    break;
            }
        }
    }
}

public PDDocumentCatalog getDocumentCatalog()
{
    if (documentCatalog == null)
    {
        COSDictionary trailer = document.getTrailer();
        COSDictionary dictionary = trailer.getCOSDictionary(COSName.ROOT);
        if (dictionary != null)
        {
            documentCatalog = new PDDocumentCatalog(this, dictionary);
        }
        else
        {
            documentCatalog = new PDDocumentCatalog(this);
        }
    }
    return documentCatalog;
}

public PDAcroForm getAcroForm(PDDocumentFixup acroFormFixup)
{
    if (acroFormFixup != null && acroFormFixup != acroFormFixupApplied)
    {
        acroFormFixup.apply();
        cachedAcroForm = null;
        acroFormFixupApplied =  acroFormFixup;
    }
    else if (acroFormFixupApplied != null)
    {
        LOG.debug("AcroForm content has already been retrieved with fixes applied - original content changed because of that");
    }
    if (cachedAcroForm == null)
    {
        COSDictionary dict = root.getCOSDictionary(COSName.ACRO_FORM);
        cachedAcroForm = dict == null ? null : new PDAcroForm(document, dict);
    }
    return cachedAcroForm;
}

