public PDColorSpace getColorSpace() throws IOException
{
    if (colorSpace == null)
    {
        COSBase cosBase = getCOSObject().getItem(COSName.COLORSPACE, COSName.CS);
        if (cosBase != null)
        {
            COSObject indirect = null;
            if (cosBase instanceof COSObject &&
                    resources != null && resources.getResourceCache() != null)
            {
                // PDFBOX-4022: use the resource cache because several images
                // might have the same colorspace indirect object.
                indirect = (COSObject) cosBase;
                colorSpace = resources.getResourceCache().getColorSpace(indirect);
                if (colorSpace != null)
                {
                    return colorSpace;
                }
            }
            colorSpace = PDColorSpace.create(cosBase, resources);
            if (indirect != null)
            {
                resources.getResourceCache().put(indirect, colorSpace);
            }
        }
        else if (isStencil())
        {
            // stencil mask color space must be gray, it is often missing
            colorSpace = PDDeviceGray.INSTANCE;
        }
        else
        {
            initJPXValues();
        }
        if (colorSpace == null)
        {
            // an image without a color space is always broken
            throw new IOException("could not determine color space");
        }
    }
    return colorSpace;
}

public PDColorSpace getAlternateColorSpace() throws IOException
{
    COSBase alternate = stream.getCOSObject().getDictionaryObject(COSName.ALTERNATE);
    COSArray alternateArray;
    if(alternate == null)
    {
        alternateArray = new COSArray();
        int numComponents = getNumberOfComponents();
        COSName csName;
        switch (numComponents)
        {
            case 1:
                csName = COSName.DEVICEGRAY;
                break;
            case 3:
                csName = COSName.DEVICERGB;
                break;
            case 4:
                csName = COSName.DEVICECMYK;
                break;
            default:
                throw new IOException("Unknown color space number of components:" + numComponents);
        }
        alternateArray.add(csName);
    }
    else
    {
        if(alternate instanceof COSArray)
        {
            alternateArray = (COSArray)alternate;
        }
        else if(alternate instanceof COSName)
        {
            alternateArray = new COSArray();
            alternateArray.add(alternate);
        }
        else
        {
            throw new IOException("Error: expected COSArray or COSName and not " +
                alternate.getClass().getName());
        }
    }
    return PDColorSpace.create(alternateArray);
}

public RadialShadingContext(PDShadingType3 shading, ColorModel colorModel,
                            AffineTransform xform, Matrix matrix, Rectangle deviceBounds)
                            throws IOException
{
    super(shading, colorModel, xform, matrix);
    this.radialShadingType = shading;
    coords = shading.getCoords().toFloatArray();

    // domain values
    if (this.radialShadingType.getDomain() != null)
    {
        domain = shading.getDomain().toFloatArray();
    }
    else
    {
        // set default values
        domain = new float[] { 0, 1 };
    }

    // extend values
    COSArray extendValues = shading.getExtend();
    if (extendValues != null)
    {
        extend = new boolean[2];
        extend[0] = ((COSBoolean) extendValues.getObject(0)).getValue();
        extend[1] = ((COSBoolean) extendValues.getObject(1)).getValue();
    }
    else
    {
        // set default values
        extend = new boolean[] { false, false };
    }
    // calculate some constants to be used in getRaster
    x1x0 = coords[3] - coords[0];
    y1y0 = coords[4] - coords[1];
    r1r0 = coords[5] - coords[2];
    r0pow2 = Math.pow(coords[2], 2);
    denom = Math.pow(x1x0, 2) + Math.pow(y1y0, 2) - Math.pow(r1r0, 2);
    d1d0 = domain[1] - domain[0];

    try
    {
        // get inverse transform to be independent of current user / device space 
        // when handling actual pixels in getRaster()
        rat = matrix.createAffineTransform().createInverse();
        rat.concatenate(xform.createInverse());
    }
    catch (NoninvertibleTransformException ex)
    {
        LOG.error(ex.getMessage() + ", matrix: " + matrix, ex);
        rat = new AffineTransform();
    }

    // shading space -> device space
    AffineTransform shadingToDevice = (AffineTransform)xform.clone();
    shadingToDevice.concatenate(matrix.createAffineTransform());

    // worst case for the number of steps is opposite diagonal corners, so use that
    double dist = Math.sqrt(Math.pow(deviceBounds.getMaxX() - deviceBounds.getMinX(), 2) +
                            Math.pow(deviceBounds.getMaxY() - deviceBounds.getMinY(), 2));
    factor = (int) Math.ceil(dist);

    // build the color table for the given number of steps
    colorTable = calcColorTable();
}

public ShadingContext(PDShading shading, ColorModel cm, AffineTransform xform,
                      Matrix matrix) throws IOException
{
    this.shading = shading;
    shadingColorSpace = shading.getColorSpace();

    // create the output color model using RGB+alpha as color space
    ColorSpace outputCS = ColorSpace.getInstance(ColorSpace.CS_sRGB);
    outputColorModel = new ComponentColorModel(outputCS, true, false, Transparency.TRANSLUCENT,
            DataBuffer.TYPE_BYTE);

    // get background values if available
    COSArray bg = shading.getBackground();
    if (bg != null)
    {
        background = bg.toFloatArray();
        rgbBackground = convertToRGB(background);
    }
}

public FDFAnnotationLine(Element element) throws IOException
{
    super(element);
    annot.setName(COSName.SUBTYPE, SUBTYPE);

    String startCoords = element.getAttribute("start");
    if (startCoords == null || startCoords.isEmpty())
    {
        throw new IOException("Error: missing attribute 'start'");
    }
    String endCoords = element.getAttribute("end");
    if (endCoords == null || endCoords.isEmpty())
    {
        throw new IOException("Error: missing attribute 'end'");
    }
    String line = startCoords + "," + endCoords;
    String[] lineValues = line.split(",");
    if (lineValues.length != 4)
    {
        throw new IOException("Error: wrong amount of line coordinates");
    }
    float[] values = new float[4];
    for (int i = 0; i < 4; i++)
    {
        values[i] = Float.parseFloat(lineValues[i]);
    }
    setLine(values);

    String leaderLine = element.getAttribute("leaderLength");
    if (leaderLine != null && !leaderLine.isEmpty())
    {
        setLeaderLength(Float.parseFloat(leaderLine));
    }

    String leaderLineExtension = element.getAttribute("leaderExtend");
    if (leaderLineExtension != null && !leaderLineExtension.isEmpty())
    {
        setLeaderExtend(Float.parseFloat(leaderLineExtension));
    }

    String leaderLineOffset = element.getAttribute("leaderOffset");
    if (leaderLineOffset != null && !leaderLineOffset.isEmpty())
    {
        setLeaderOffset(Float.parseFloat(leaderLineOffset));
    }

    String startStyle = element.getAttribute("head");
    if (startStyle != null && !startStyle.isEmpty())
    {
        setStartPointEndingStyle(startStyle);
    }
    String endStyle = element.getAttribute("tail");
    if (endStyle != null && !endStyle.isEmpty())
    {
        setEndPointEndingStyle(endStyle);
    }

    String color = element.getAttribute("interior-color");
    if (color != null && color.length() == 7 && color.charAt(0) == '#')
    {
        int colorValue = Integer.parseInt(color.substring(1, 7), 16);
        setInteriorColor(new Color(colorValue));
    }

    String caption = element.getAttribute("caption");
    if ("yes".equals(caption))
    {
        setCaption(true);

        String captionH = element.getAttribute("caption-offset-h");
        if (captionH != null && !captionH.isEmpty())
        {
            setCaptionHorizontalOffset(Float.parseFloat(captionH));
        }

        String captionV = element.getAttribute("caption-offset-v");
        if (captionV != null && !captionV.isEmpty())
        {
            setCaptionVerticalOffset(Float.parseFloat(captionV));
        }

        String captionStyle = element.getAttribute("caption-style");
        if (captionStyle != null && !captionStyle.isEmpty())
        {
            setCaptionStyle(captionStyle);
        }
    }
}

