}

public String getURI()
{
    COSBase base = action.getDictionaryObject(COSName.URI);
    if (base instanceof COSString)
    {
        byte[] bytes = ((COSString) base).getBytes();
        if (bytes.length >= 2)
        {
            // UTF-16 (BE)
            if ((bytes[0] & 0xFF) == 0xFE && (bytes[1] & 0xFF) == 0xFF)
            {
                return action.getString(COSName.URI);
            }
            // UTF-16 (LE)
            if ((bytes[0] & 0xFF) == 0xFF && (bytes[1] & 0xFF) == 0xFE)
            {
                return action.getString(COSName.URI);
            }
        }
        return new String(bytes, StandardCharsets.UTF_8);
    }
    return null;
}

public FDFAnnotationLink(Element element) throws IOException
{
    super(element);
    annot.setName(COSName.SUBTYPE, SUBTYPE);
    XPath xpath = XPathFactory.newInstance().newXPath();

    try
    {
        NodeList uri = (NodeList) xpath.evaluate("OnActivation/Action/URI", element,
                XPathConstants.NODESET);
        if (uri.getLength() > 0)
        {
            Node namedItem = uri.item(0).getAttributes().getNamedItem("Name");
            if (namedItem != null && namedItem.getNodeValue() != null)
            {
                PDActionURI actionURI = new PDActionURI();
                actionURI.setURI(namedItem.getNodeValue());
                annot.setItem(COSName.A, actionURI);
            }
        }
        // GoTo is more tricky, because because page destination needs page tree
        // to convert number into PDPage object
    }
    catch (XPathExpressionException e)
    {
        LOG.debug("Error while evaluating XPath expression", e);
    }
}

public TextPosition(int pageRotation, float pageWidth, float pageHeight, Matrix textMatrix,
                    float endX, float endY, float maxHeight, float individualWidth,
                    float spaceWidth, String unicode, int[] charCodes, PDFont font,
                    float fontSize, int fontSizeInPt)
{
    this.textMatrix = textMatrix;

    this.endX = endX;
    this.endY = endY;

    this.rotation = pageRotation;

    this.maxHeight = maxHeight;
    this.pageHeight = pageHeight;
    this.pageWidth = pageWidth;

    this.widths = new float[] { individualWidth };
    this.widthOfSpace = spaceWidth;
    this.unicode = unicode;
    this.charCodes = charCodes;
    this.font = font;
    this.fontSize = fontSize;
    this.fontSizePt = fontSizeInPt;

    x = getXRot(rotation);
    if (rotation == 0 || rotation == 180)
    {
        y = this.pageHeight - getYLowerLeftRot(rotation);
    }
    else
    {
        y = this.pageWidth - getYLowerLeftRot(rotation);
    }
}

public boolean equals(Object o)
{
    if (this == o)
    {
        return true;
    }
    if (!(o instanceof TextPosition))
    {
        return false;
    }

    TextPosition that = (TextPosition) o;

    if (Float.compare(that.endX, endX) != 0)
    {
        return false;
    }
    if (Float.compare(that.endY, endY) != 0)
    {
        return false;
    }
    if (Float.compare(that.maxHeight, maxHeight) != 0)
    {
        return false;
    }
    if (rotation != that.rotation)
    {
        return false;
    }
    if (Float.compare(that.x, x) != 0)
    {
        return false;
    }
    if (Float.compare(that.y, y) != 0)
    {
        return false;
    }
    if (Float.compare(that.pageHeight, pageHeight) != 0)
    {
        return false;
    }
    if (Float.compare(that.pageWidth, pageWidth) != 0)
    {
        return false;
    }
    if (Float.compare(that.widthOfSpace, widthOfSpace) != 0)
    {
        return false;
    }
    if (Float.compare(that.fontSize, fontSize) != 0)
    {
        return false;
    }
    if (fontSizePt != that.fontSizePt)
    {
        return false;
    }
    if (!Objects.equals(textMatrix, that.textMatrix))
    {
        return false;
    }
    if (!Arrays.equals(charCodes, that.charCodes))
    {
        return false;
    }
    return Objects.equals(font, that.font);

    // If changing this method, do not compare mutable fields (PDFBOX-4701)        
}

public int hashCode()
{
    int result = textMatrix != null ? textMatrix.hashCode() : 0;
    result = 31 * result + Float.floatToIntBits(endX);
    result = 31 * result + Float.floatToIntBits(endY);
    result = 31 * result + Float.floatToIntBits(maxHeight);
    result = 31 * result + rotation;
    result = 31 * result + Float.floatToIntBits(x);
    result = 31 * result + Float.floatToIntBits(y);
    result = 31 * result + Float.floatToIntBits(pageHeight);
    result = 31 * result + Float.floatToIntBits(pageWidth);
    result = 31 * result + Float.floatToIntBits(widthOfSpace);
    result = 31 * result + Arrays.hashCode(charCodes);
    result = 31 * result + (font != null ? font.hashCode() : 0);
    result = 31 * result + Float.floatToIntBits(fontSize);
    result = 31 * result + fontSizePt;
    return result;
}

public COSBase parseObject(long objectNumber) throws IOException
{
    COSBase streamObject = null;
    try
    {
        Integer objectOffset = privateReadObjectNumbers().get(objectNumber);
        if (objectOffset != null)
        {
            // jump to the offset of the first object
            long currentPosition = source.getPosition();
            if (firstObject > 0 && currentPosition < firstObject)
            {
                source.skip(firstObject - (int) currentPosition);
            }
            // jump to the offset of the object to be parsed
            source.skip(objectOffset);
            streamObject = parseDirObject();
            if (streamObject != null)
            {
                streamObject.setDirect(false);
            }
        }
    }
    finally
    {
        source.close();
        document = null;
    }
    return streamObject;
}

public Object getValue(Integer index) throws IOException
{
    Map<Integer, COSObjectable> numbers = getNumbers();
    if (numbers != null)
    {
        return numbers.get(index);
    }
    Object retval = null;
    List<PDNumberTreeNode> kids = getKids();
    if (kids != null)
    {
        for (int i = 0; i < kids.size() && retval == null; i++)
        {
            PDNumberTreeNode childNode = kids.get(i);
            if (childNode.getLowerLimit().compareTo(index) <= 0 &&
                childNode.getUpperLimit().compareTo(index) >= 0)
            {
                retval = childNode.getValue(index);
            }
        }
    }
    else
    {
        LOG.warn("NumberTreeNode does not have \"nums\" nor \"kids\" objects.");
    }
    return retval;
}

public void setKids( List<? extends PDNumberTreeNode> kids )
{
    if (kids != null && !kids.isEmpty())
    {
        PDNumberTreeNode firstKid = kids.get(0);
        PDNumberTreeNode lastKid = kids.get(kids.size() - 1);
        Integer lowerLimit = firstKid.getLowerLimit();
        setLowerLimit(lowerLimit);
        Integer upperLimit = lastKid.getUpperLimit();
        setUpperLimit(upperLimit);
        node.setItem(COSName.KIDS, new COSArray(kids));
    }
    else if ( node.getDictionaryObject( COSName.NUMS ) == null )
    {
        // Remove limits if there are no kids and no numbers set.
        node.setItem( COSName.LIMITS, null);
        node.setItem(COSName.KIDS, null);
    }
}

public void setNumbers( Map<Integer, ? extends COSObjectable> numbers )
{
    if( numbers == null )
    {
        node.setItem( COSName.NUMS, (COSObjectable)null );
        node.setItem( COSName.LIMITS, (COSObjectable)null);
    }
    else
    {
        List<Integer> keys = new ArrayList<>( numbers.keySet() );
        Collections.sort( keys );
        COSArray array = new COSArray();
        for (Integer key : keys)
        {
            array.add( COSInteger.get( key ) );
            COSObjectable obj = numbers.get( key );
            array.add(obj == null ? COSNull.NULL : obj);
        }
        Integer lower = null;
        Integer upper = null;
        if (!keys.isEmpty())
        {
            lower = keys.get( 0 );
            upper = keys.get( keys.size()-1 );
        }
        setUpperLimit( upper );
        setLowerLimit( lower );
        node.setItem( COSName.NUMS, array );
    }
}

public String toString()
{
    StringBuilder sb = new StringBuilder(dictionary.getNameAsString(COSName.SUBTYPE));
    sb.append('{');
    PDDeviceNProcess process = getProcess();
    if (process != null)
    {
        sb.append(process);
        sb.append(' ');
    }

    Map<String, PDSeparation> colorants;
    try
    {
        colorants = getColorants(null);
        sb.append("Colorants{");
        for (Map.Entry<String, PDSeparation> col : colorants.entrySet())
        {
            sb.append('\"');
            sb.append(col.getKey());
            sb.append("\": ");
            sb.append(col.getValue());
            sb.append(' ');
        }
        sb.append('}');
    }
    catch (IOException e)
    {
        LOG.debug("Couldn't get the colorants information - returning 'ERROR' instead'", e);
        sb.append("ERROR");
    }
    sb.append('}');
    return sb.toString();
}

