public void close() throws IOException
{
    if (closed)
    {
        return;
    }

    // Make sure that:
    // - first Exception is kept
    // - all COSStreams are closed
    // - stream cache is closed
    // - there's a way to see which errors occurred
    IOException firstException = null;

    // close all open I/O streams
    for (COSObject object : objectPool.values())
    {
        if (!object.isObjectNull())
        {
            COSBase cosObject = object.getObject();
            if (cosObject instanceof COSStream)
            {
                firstException = IOUtils.closeAndLogException((COSStream) cosObject, LOG,
                        "COSStream", firstException);
            }
        }
    }

    for (COSStream stream : streams)
    {
        firstException = IOUtils.closeAndLogException(stream, LOG, "COSStream", firstException);
    }

    if (streamCache != null)
    {
        firstException = IOUtils.closeAndLogException(streamCache, LOG, "Stream Cache",
                firstException);
    }
    closed = true;

    // rethrow first exception to keep method contract
    if (firstException != null)
    {
        throw firstException;
    }
}

public COSString(String text, boolean forceHex)
{
    forceHexForm = forceHex;
    // check whether the string uses only characters available in PDFDocEncoding
    boolean isOnlyPDFDocEncoding = true;
    for (char c : text.toCharArray())
    {
        if (!PDFDocEncoding.containsChar(c))
        {
            isOnlyPDFDocEncoding = false;
            break;
        }
    }

    if (isOnlyPDFDocEncoding)
    {
        // PDFDocEncoded string
        bytes = PDFDocEncoding.getBytes(text);
    }
    else
    {
        // UTF-16BE encoded string with a leading byte order marker
        byte[] data = text.getBytes(StandardCharsets.UTF_16BE);
        bytes = new byte[data.length + 2];
        bytes[0] = (byte) 0xFE;
        bytes[1] = (byte) 0xFF;
        System.arraycopy(data, 0, bytes, 2, data.length);
    }
}

public PDType1CFont(COSDictionary fontDictionary) throws IOException
{
    super(fontDictionary);

    boolean fontIsDamaged = false;
    CFFType1Font cffEmbedded = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null)
    {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null)
        {
            try (RandomAccessRead randomAccessRead = fd.getFontFile3().getCOSObject()
                    .createView())
            {
                if (randomAccessRead.length() == 0)
                {
                    LOG.error("Invalid data for embedded Type1C font " + getName());
                }
                else
                {
                    // note: this could be an OpenType file, fortunately CFFParser can handle that
                    CFFParser cffParser = new CFFParser();
                    CFFFont parsedCffFont = cffParser.parse(randomAccessRead).get(0);
                    if (parsedCffFont instanceof CFFType1Font)
                    {
                        cffEmbedded = (CFFType1Font) parsedCffFont;
                    }
                    else
                    {
                        LOG.error("Expected CFFType1Font, got "
                                + parsedCffFont.getClass().getSimpleName());
                        fontIsDamaged = true;
                    }
                }
            }
            catch (IOException e)
            {
                LOG.error("Can't read the embedded Type1C font " + getName(), e);
                fontIsDamaged = true;
            }
        }
    }
    isDamaged = fontIsDamaged;
    cffFont = cffEmbedded;
    if (cffFont != null)
    {
        genericFont = cffFont;
        isEmbedded = true;
    }
    else
    {
        FontMapping<FontBoxFont> mapping = FontMappers.instance()
                                                      .getFontBoxFont(getBaseFont(), fd);
        genericFont = mapping.getFont();

        if (mapping.isFallback())
        {
            LOG.warn("Using fallback font " + genericFont.getName() + " for " + getBaseFont());
        }
        isEmbedded = false;
    }
    readEncoding();
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

