public void writePDF(OutputStream output) throws IOException
{
    output.write('/');
    byte[] bytes = getName().getBytes(StandardCharsets.UTF_8);
    for (byte b : bytes)
    {
        int current = b & 0xFF;

        // be more restrictive than the PDF spec, "Name Objects", see PDFBOX-2073
        if (current >= 'A' && current <= 'Z' ||
                current >= 'a' && current <= 'z' ||
                current >= '0' && current <= '9' ||
                current == '+' ||
                current == '-' ||
                current == '_' ||
                current == '@' ||
                current == '*' ||
                current == '$' ||
                current == ';' ||
                current == '.')
        {
            output.write(current);
        }
        else
        {
            output.write('#');
            Hex.writeHexByte(b, output);
        }
    }
}

public DictionaryEncoding(COSDictionary fontEncoding, boolean isNonSymbolic, Encoding builtIn)
{
    encoding = fontEncoding;

    Encoding base = null;
    boolean hasBaseEncoding = encoding.containsKey(COSName.BASE_ENCODING);
    if (hasBaseEncoding)
    {
        COSName name = encoding.getCOSName(COSName.BASE_ENCODING);
        base = Encoding.getInstance(name); // null when the name is invalid
    }

    if (base == null)
    {
        if (isNonSymbolic)
        {
            // Otherwise, for a nonsymbolic font, it is StandardEncoding
            base = StandardEncoding.INSTANCE;
        }
        else
        {
            // and for a symbolic font, it is the font's built-in encoding.
            if (builtIn != null)
            {
                base = builtIn;
            }
            else
            {
                // triggering this error indicates a bug in PDFBox. Every font should always have
                // a built-in encoding, if not, we parsed it incorrectly.
                throw new IllegalArgumentException("Symbolic fonts must have a built-in " + 
                                                   "encoding");
            }
        }
    }
    baseEncoding = base;

    codeToName.putAll(baseEncoding.codeToName);
    inverted.putAll(baseEncoding.inverted);
    applyDifferences();
}

public String toUnicode(int code)
{
    // if the font dictionary containsName a ToUnicode CMap, use that CMap
    if (toUnicodeCMap != null)
    {
        if (toUnicodeCMap.getName() != null && 
            toUnicodeCMap.getName().startsWith("Identity-") && 
                (dict.getCOSName(COSName.TO_UNICODE) != null
                        || !toUnicodeCMap.hasUnicodeMappings()))
        {
            // handle the undocumented case of using Identity-H/V as a ToUnicode CMap, this
            // isn't actually valid as the Identity-x CMaps are code->CID maps, not
            // code->Unicode maps. See sample_fonts_solidconvertor.pdf for an example.
            // PDFBOX-3123: do this only if the /ToUnicode entry is a name
            // PDFBOX-4322: identity streams are OK too
            return new String(new char[] { (char) code });
        }
        else
        {
            if (code < 256 && !(this instanceof PDType0Font))
            {
                COSName encoding = dict.getCOSName(COSName.ENCODING);
                if (encoding != null && !encoding.getName().startsWith("Identity"))
                {
                    // due to the conversion to an int it is no longer possible to determine
                    // if the code is based on a one or two byte value. We should consider to
                    // refactor that part of the code.
                    // However, simple fonts with a predefined encoding are using one byte codes so that
                    // we can limit the CMap mappings to one byte codes by passing the origin length
                    return toUnicodeCMap.toUnicode(code, 1);
                }
            }
            return toUnicodeCMap.toUnicode(code);
        }
    }

    // if no value has been produced, there is no way to obtain Unicode for the character.
    // this behaviour can be overridden is subclasses, but this method *must* return null here
    return null;
}

public AxialShadingContext(PDShadingType2 shading, ColorModel colorModel, AffineTransform xform,
                           Matrix matrix, Rectangle deviceBounds) throws IOException
{
    super(shading, colorModel, xform, matrix);
    this.axialShadingType = shading;
    coords = shading.getCoords().toFloatArray();

    // domain values
    if (shading.getDomain() != null)
    {
        domain = shading.getDomain().toFloatArray();
    }
    else
    {
        // set default values
        domain = new float[] { 0, 1 };
    }
    // extend values
    COSArray extendValues = shading.getExtend();
    if (extendValues != null)
    {
        extend = new boolean[2];
        extend[0] = ((COSBoolean) extendValues.getObject(0)).getValue();
        extend[1] = ((COSBoolean) extendValues.getObject(1)).getValue();
    }
    else
    {
        // set default values
        extend = new boolean[] { false, false };
    }
    // calculate some constants to be used in getRaster
    x1x0 = coords[2] - coords[0];
    y1y0 = coords[3] - coords[1];
    d1d0 = domain[1] - domain[0];
    denom = Math.pow(x1x0, 2) + Math.pow(y1y0, 2);

    try
    {
        // get inverse transform to be independent of current user / device space 
        // when handling actual pixels in getRaster()
        rat = matrix.createAffineTransform().createInverse();
        rat.concatenate(xform.createInverse());
    }
    catch (NoninvertibleTransformException ex)
    {
        LOG.error(ex.getMessage() + ", matrix: " + matrix, ex);
        rat = new AffineTransform();
    }

    // shading space -> device space
    AffineTransform shadingToDevice = (AffineTransform)xform.clone();
    shadingToDevice.concatenate(matrix.createAffineTransform());

    // worst case for the number of steps is opposite diagonal corners, so use that
    double dist = Math.sqrt(Math.pow(deviceBounds.getMaxX() - deviceBounds.getMinX(), 2) +
                            Math.pow(deviceBounds.getMaxY() - deviceBounds.getMinY(), 2));
    factor = (int) Math.ceil(dist);

    // build the color table for the given number of steps
    colorTable = calcColorTable();
}

