public PDCIDFontType0(COSDictionary fontDictionary, PDType0Font parent) throws IOException
{
    super(fontDictionary, parent);

    boolean fontIsDamaged = false;
    CFFFont cffFont = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null)
    {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null)
        {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView())
            {
                if (randomAccessRead.length() > 0 && randomAccessRead.peek() == '%')
                {
                    // PDFBOX-2642 contains a corrupt PFB font instead of a CFF
                    LOG.warn("Found PFB but expected embedded CFF font " + fd.getFontName());
                    fontIsDamaged = true;
                }
                else
                {
                    CFFParser cffParser = new CFFParser();
                    cffFont = cffParser.parse(randomAccessRead).get(0);
                }
            }
            catch (IOException e)
            {
                LOG.error("Can't read the embedded CFF font " + fd.getFontName(), e);
                fontIsDamaged = true;
            }
        }
    }

    if (cffFont != null)
    {
        // embedded
        if (cffFont instanceof CFFCIDFont)
        {
            cidFont = (CFFCIDFont)cffFont;
            t1Font = null;
        }
        else
        {
            cidFont = null;
            t1Font = cffFont;
        }
        cid2gid = readCIDToGIDMap();
        isEmbedded = true;
        isDamaged = false;
    }
    else
    {
        // find font or substitute
        CIDFontMapping mapping = FontMappers.instance()
                                            .getCIDFont(getBaseFont(), getFontDescriptor(),
                                                        getCIDSystemInfo());
        FontBoxFont font;
        if (mapping.isCIDFont())
        {
            cffFont = mapping.getFont().getCFF().getFont();
            if (cffFont instanceof CFFCIDFont)
            {
                cidFont = (CFFCIDFont) cffFont;
                t1Font = null;
                font = cidFont;
            }
            else
            {
                // PDFBOX-3515: OpenType fonts are loaded as CFFType1Font
                CFFType1Font f = (CFFType1Font) cffFont;
                cidFont = null;
                t1Font = f;
                font = f;
            }
        }
        else
        {
            cidFont = null;
            t1Font = mapping.getTrueTypeFont();
            font = t1Font;
        }

        if (mapping.isFallback())
        {
            LOG.warn("Using fallback " + font.getName() + " for CID-keyed font " +
                     getBaseFont());
        }
        isEmbedded = false;
        isDamaged = fontIsDamaged;
    }
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

public PDTrueTypeFont(COSDictionary fontDictionary) throws IOException
{
    super(fontDictionary);

    TrueTypeFont ttfFont = null;
    boolean fontIsDamaged = false;
    if (getFontDescriptor() != null)
    {
        PDFontDescriptor fd = super.getFontDescriptor();
        PDStream ff2Stream = fd.getFontFile2();
        if (ff2Stream != null)
        {
            RandomAccessRead view = null;
            try
            {
                view = ff2Stream.getCOSObject().createView();
                // embedded
                TTFParser ttfParser = getParser(view, true);
                ttfFont = ttfParser.parse(view);
                ttfFont.close();
            }
            catch (IOException e)
            {
                LOG.warn("Could not read embedded TTF for font " + getBaseFont(), e);
                fontIsDamaged = true;
                IOUtils.closeQuietly(view);
            }
        }
    }
    isEmbedded = ttfFont != null;
    isDamaged = fontIsDamaged;

    // substitute
    if (ttfFont == null)
    {
        FontMapping<TrueTypeFont> mapping = FontMappers.instance()
                                                       .getTrueTypeFont(getBaseFont(),
                                                                        getFontDescriptor());
        ttfFont = mapping.getFont();

        if (mapping.isFallback())
        {
            LOG.warn("Using fallback font " + ttfFont + " for " + getBaseFont());
        }
    }
    otf = ttfFont instanceof OpenTypeFont && ((OpenTypeFont) ttfFont).isSupportedOTF()
            ? (OpenTypeFont) ttfFont : null;
    ttf = ttfFont;
    readEncoding();
}

public PDType0Font(COSDictionary fontDictionary) throws IOException
{
    super(fontDictionary);

    gsubData = GsubData.NO_DATA_FOUND;
    cmapLookup = null;

    COSArray descendantFonts = dict.getCOSArray(COSName.DESCENDANT_FONTS);
    if (descendantFonts == null)
    {
        throw new IOException("Missing descendant font array");
    }
    if (descendantFonts.size() == 0)
    {
        throw new IOException("Descendant font array is empty");
    }
    COSBase descendantFontDictBase = descendantFonts.getObject(0);
    if (!(descendantFontDictBase instanceof COSDictionary))
    {
        throw new IOException("Missing descendant font dictionary");
    }
    if (!COSName.FONT.equals(
            ((COSDictionary) descendantFontDictBase).getCOSName(COSName.TYPE, COSName.FONT)))
    {
        throw new IOException("Missing or wrong type in descendant font dictionary");
    }
    descendantFont = PDFontFactory.createDescendantFont((COSDictionary) descendantFontDictBase, this);
    readEncoding();
    fetchCMapUCS2();
}

public void addSignature(PDSignature sigObject, SignatureInterface signatureInterface,
                         SignatureOptions options) throws IOException
{
    if (signatureAdded)
    {
        throw new IllegalStateException("Only one signature may be added in a document");
    }
    signatureAdded = true;

    // Reserve content
    // We need to reserve some space for the signature. Some signatures including
    // big certificate chain and we need enough space to store it.
    int preferredSignatureSize = options.getPreferredSignatureSize();
    if (preferredSignatureSize > 0)
    {
        sigObject.setContents(new byte[preferredSignatureSize]);
    }
    else
    {
        sigObject.setContents(new byte[SignatureOptions.DEFAULT_SIGNATURE_SIZE]);
    }

    // Reserve ByteRange, will be overwritten in COSWriter
    sigObject.setByteRange(RESERVE_BYTE_RANGE);

    signInterface = signatureInterface;

    // Create SignatureForm for signature and append it to the document

    // Get the first valid page
    PDPageTree pageTree = getPages();
    int pageCount = pageTree.getCount();
    if (pageCount == 0)
    {
        throw new IllegalStateException("Cannot sign an empty document");
    }

    // Get the AcroForm from the Root-Dictionary and append the annotation
    PDDocumentCatalog catalog = getDocumentCatalog();
    PDAcroForm acroForm = catalog.getAcroForm(null);
    catalog.getCOSObject().setNeedToBeUpdated(true);

    if (acroForm == null)
    {
        acroForm = new PDAcroForm(this);
        catalog.setAcroForm(acroForm);
    }
    else
    {
        acroForm.getCOSObject().setNeedToBeUpdated(true);
    }

    PDSignatureField signatureField = null;
    COSArray fieldArray = acroForm.getCOSObject().getCOSArray(COSName.FIELDS);
    if (fieldArray != null)
    {
        fieldArray.setNeedToBeUpdated(true);
        signatureField = findSignatureField(acroForm.getFieldIterator(), sigObject);
    }
    else
    {
        acroForm.getCOSObject().setItem(COSName.FIELDS, new COSArray());
    }
    PDAnnotationWidget firstWidget;
    PDPage page;
    if (signatureField == null)
    {
        signatureField = new PDSignatureField(acroForm);
        // append the signature object
        signatureField.setValue(sigObject);
        firstWidget = signatureField.getWidgets().get(0);
        int startIndex = Math.min(Math.max(options.getPage(), 0), pageCount - 1);
        page = pageTree.get(startIndex);
        // backward linking
        firstWidget.setPage(page);
    }
    else
    {
        firstWidget = signatureField.getWidgets().get(0);
        sigObject.getCOSObject().setNeedToBeUpdated(true);
        page = null;
    }

    // TODO This "overwrites" the settings of the original signature field which might not be intended by the user
    // better make it configurable (not all users need/want PDF/A but their own setting):

    // to conform PDF/A-1 requirement:
    // The /F key's Print flag bit shall be set to 1 and 
    // its Hidden, Invisible and NoView flag bits shall be set to 0
    firstWidget.setPrinted(true);
    // This may be troublesome if several form fields are signed,
    // see thread from PDFBox users mailing list 17.2.2021 - 19.2.2021
    // https://mail-archives.apache.org/mod_mbox/pdfbox-users/202102.mbox/thread
    // better set the printed flag in advance

    // Set the AcroForm Fields
    List<PDField> acroFormFields = acroForm.getFields();
    acroForm.getCOSObject().setDirect(true);
    acroForm.setSignaturesExist(true);
    acroForm.setAppendOnly(true);

    boolean checkFields = checkSignatureField(acroForm.getFieldIterator(), signatureField);
    if (checkFields)
    {
        signatureField.getCOSObject().setNeedToBeUpdated(true);
    }
    else
    {
        acroFormFields.add(signatureField);
    }

    // Get the object from the visual signature
    COSDocument visualSignature = options.getVisualSignature();

    // Distinction of case for visual and non-visual signature
    if (visualSignature == null)
    {
        prepareNonVisibleSignature(firstWidget);
    }
    else
    {
        prepareVisibleSignature(firstWidget, acroForm, visualSignature);
    }

    if (page != null)
    {
        // Create Annotation / Field for signature
        List<PDAnnotation> annotations = page.getAnnotations();

        // Get the annotations of the page and append the signature-annotation to it
        // take care that page and acroforms do not share the same array (if so, we don't need to add it twice)
        if (!(checkFields &&
              annotations instanceof COSArrayList &&
              acroFormFields instanceof COSArrayList &&
              ((COSArrayList) annotations).toList().
                      equals(((COSArrayList) acroFormFields).toList())))
        {
            // use check to prevent the annotation widget from appearing twice
            if (checkSignatureAnnotation(annotations, firstWidget))
            {
                firstWidget.getCOSObject().setNeedToBeUpdated(true);
            }
            else
            {
                annotations.add(firstWidget);
            }   
        }

        // Make /Annots a direct object by reassigning it,
        // to avoid problem if it is an existing indirect object: 
        // it would not be updated in incremental save, and if we'd set the /Annots array "to be updated" 
        // while keeping it indirect, Adobe Reader would claim that the document had been modified.
        page.setAnnotations(annotations);

        page.getCOSObject().setNeedToBeUpdated(true);
    }
}

public void close() throws IOException
{
    if (!document.isClosed())
    {
         // Make sure that:
        // - first Exception is kept
        // - all IO resources are closed
        // - there's a way to see which errors occurred

        IOException firstException = null;

        // close resources and COSWriter
        if (signingSupport != null)
        {
            firstException = IOUtils.closeAndLogException(signingSupport, LOG, "SigningSupport", firstException);
        }

        // close all intermediate I/O streams
        firstException = IOUtils.closeAndLogException(document, LOG, "COSDocument", firstException);

        // close the source PDF stream, if we read from one
        if (pdfSource != null)
        {
            firstException = IOUtils.closeAndLogException(pdfSource, LOG, "RandomAccessRead pdfSource", firstException);
        }

        // close fonts
        for (TrueTypeFont ttf : fontsToClose)
        {
            firstException = IOUtils.closeAndLogException(ttf, LOG, "TrueTypeFont", firstException);
        }

        // rethrow first exception to keep method contract
        if (firstException != null)
        {
            throw firstException;
        }
    }
}

