public void protect(ProtectionPolicy policy) throws IOException
{
    if (isAllSecurityToBeRemoved())
    {
        LOG.warn("do not call setAllSecurityToBeRemoved(true) before calling protect(), "
                + "as protect() implies setAllSecurityToBeRemoved(false)");
        setAllSecurityToBeRemoved(false);
    }

    if (!isEncrypted())
    {
        encryption = new PDEncryption();
    }

    SecurityHandler<ProtectionPolicy> securityHandler =
            SecurityHandlerFactory.INSTANCE.newSecurityHandlerForPolicy(policy);
    if (securityHandler == null)
    {
        throw new IOException("No security handler for policy " + policy);
    }

    getEncryption().setSecurityHandler(securityHandler);
}

public ExternalSigningSupport saveIncrementalForExternalSigning(OutputStream output) throws IOException
{
    subsetDesignatedFonts();
    if (pdfSource == null)
    {
        throw new IllegalStateException("document was not loaded from a file or a stream");
    }
    // PDFBOX-3978: getLastSignatureDictionary() not helpful if signing into a template
    // that is not the last signature. So give higher priority to signature with update flag.
    PDSignature foundSignature = null;
    for (PDSignature sig : getSignatureDictionaries())
    {
        foundSignature = sig;
        if (sig.getCOSObject().isNeedToBeUpdated())
        {
            break;
        }
    }

    if (foundSignature == null)
    {
        throw new IllegalStateException("document does not contain signature fields");
    }

    int[] byteRange = foundSignature.getByteRange();
    if (!Arrays.equals(byteRange, RESERVE_BYTE_RANGE))
    {
        throw new IllegalStateException("signature reserve byte range has been changed "
                + "after addSignature(), please set the byte range that existed after addSignature()");
    }
    COSWriter writer = new COSWriter(output, pdfSource);
    writer.write(this);
    signingSupport = new SigningSupport(writer);
    return signingSupport;
}

public void write(PDDocument doc, SignatureInterface signInterface) throws IOException
{
    pdDocument = doc;
    COSDocument cosDoc = pdDocument.getDocument();
    COSDictionary trailer = cosDoc.getTrailer();
    if (incrementalUpdate)
    {
        trailer.toIncrement().exclude(trailer).forEach(base -> {
            objectsToWrite.add(base);
            if (base instanceof COSObject)
            {
                actualsAdded.add(((COSObject) base).getObject());
            }
            else
            {
                actualsAdded.add(base);
            }
        });
    }
    signatureInterface = signInterface;
    number = pdDocument.getDocument().getHighestXRefObjectNumber();
    if (incrementalUpdate)
    {
        prepareIncrement();
    }
    long idTime = pdDocument.getDocumentId() == null ? System.currentTimeMillis()
            : pdDocument.getDocumentId();

    // if the document says we should remove encryption, then we shouldn't encrypt
    if (doc.isAllSecurityToBeRemoved())
    {
        willEncrypt = false;
        // also need to get rid of the "Encrypt" in the trailer so readers 
        // don't try to decrypt a document which is not encrypted
        trailer.removeItem(COSName.ENCRYPT);
    }
    else
    {
        if (pdDocument.getEncryption() != null)
        {
            if (!incrementalUpdate)
            {
                SecurityHandler<? extends ProtectionPolicy> securityHandler =
                        pdDocument.getEncryption().getSecurityHandler();
                if (!securityHandler.hasProtectionPolicy())
                {
                    throw new IllegalStateException("PDF contains an encryption dictionary, please remove it with "
                            + "setAllSecurityToBeRemoved() or set a protection policy with protect()");
                }
                securityHandler.prepareDocumentForEncryption(pdDocument);
            }
            willEncrypt = true;
        }
        else
        {
            willEncrypt = false;
        }
    }

    COSArray idArray;
    boolean missingID = true;
    COSBase base = trailer.getDictionaryObject(COSName.ID);
    if (base instanceof COSArray)
    {
        idArray = (COSArray) base;
        if (idArray.size() == 2)
        {
            missingID = false;
        }
    }
    else
    {
        idArray = new COSArray();
    }
    if( missingID || incrementalUpdate)
    {
        MessageDigest sha256;
        try
        {
            sha256 = MessageDigest.getInstance("SHA-256");
        }
        catch (NoSuchAlgorithmException e)
        {
            // should never happen
            throw new RuntimeException(e);
        }

        // algorithm says to use time/path/size/values in doc to generate the id.
        // we don't have path or size, so do the best we can
        sha256.update( Long.toString(idTime).getBytes(StandardCharsets.ISO_8859_1) );

        COSDictionary info = trailer.getCOSDictionary(COSName.INFO);
        if( info != null )
        {
            for (COSBase cosBase : info.getValues())
            {
                sha256.update(cosBase.toString().getBytes(StandardCharsets.ISO_8859_1));
            }
        }
        // reuse origin documentID if available as first value
        COSString firstID = missingID ? new COSString(sha256.digest()) : (COSString) idArray.get(0);
        // it's ok to use the same ID for the second part if the ID is created for the first time
        COSString secondID = missingID ? firstID : new COSString(sha256.digest());
        idArray = new COSArray();
        idArray.add( firstID );
        idArray.add( secondID );
        trailer.setItem(COSName.ID, idArray);
    }
    cosDoc.accept(this);
    if (!incrementalUpdate)
    {
        cosDoc.setHighestXRefObjectNumber(number);
    }
}

public void getIndirectObjectKeys(Collection<COSObjectKey> indirectObjects)
{
    if (indirectObjects == null)
    {
        return;
    }
    COSObjectKey key = getKey();
    if (key != null)
    {
        // avoid endless recursions
        if (indirectObjects.contains(key))
        {
            return;
        }
        else
        {
            indirectObjects.add(key);
        }
    }
    for (Entry<COSName, COSBase> entry : items.entrySet())
    {
        COSBase cosBase = entry.getValue();
        COSObjectKey cosBaseKey = cosBase != null ? cosBase.getKey() : null;
        // avoid endless recursions
        if (COSName.PARENT.equals(entry.getKey())
                || (cosBaseKey != null && indirectObjects.contains(cosBaseKey)))
        {
            continue;
        }
        if (cosBase instanceof COSObject)
        {
            // dereference object
            cosBase = ((COSObject) cosBase).getObject();
        }
        if (cosBase instanceof COSDictionary)
        {
            // descend to included dictionary to collect all included indirect objects
            ((COSDictionary) cosBase).getIndirectObjectKeys(indirectObjects);
        }
        else if (cosBase instanceof COSArray)
        {
            // descend to included array to collect all included indirect objects
            ((COSArray) cosBase).getIndirectObjectKeys(indirectObjects);
        }
        else if (cosBaseKey != null)
        {
            // add key for all indirect objects other than COSDictionary/COSArray
            indirectObjects.add(cosBaseKey);
        }
    }
}

