public FDFField(Element fieldXML) throws IOException
{
    this();
    this.setPartialFieldName(fieldXML.getAttribute("name"));
    NodeList nodeList = fieldXML.getChildNodes();
    List<FDFField> kids = new ArrayList<>();
    for (int i = 0; i < nodeList.getLength(); i++)
    {
        Node node = nodeList.item(i);
        if (node instanceof Element)
        {
            Element child = (Element) node;
            switch (child.getTagName())
            {
                case "value":
                    setValue(XMLUtil.getNodeValue(child));
                    break;
                case "value-richtext":
                    setRichText(new COSString(XMLUtil.getNodeValue(child)));
                    break;
                case "field":
                    kids.add(new FDFField(child));
                    break;
                default:
                    break;
            }
        }
    }
    if (kids.size() > 0)
    {
        setKids(kids);
    }

}

public FDFAnnotationText(Element element) throws IOException
{
    super(element);
    annot.setName(COSName.SUBTYPE, SUBTYPE);
    String icon = element.getAttribute("icon");
    if (icon != null && !icon.isEmpty())
    {
        setIcon(element.getAttribute("icon"));
    }
    String state = element.getAttribute("state");
    if (state != null && !state.isEmpty())
    {
        String statemodel = element.getAttribute("statemodel");
        if (statemodel != null && !statemodel.isEmpty())
        {
            setState(element.getAttribute("state"));
            setStateModel(element.getAttribute("statemodel"));
        }
    }
}

public void writeXML(Writer output) throws IOException
{
    output.write("<field name=\"");
    output.write(getPartialFieldName());
    output.write("\">\n");

    Object value = getValue();

    if (value instanceof String)
    {
        output.write("<value>");
        output.write(escapeXML((String) value));
        output.write("</value>\n");
    }
    else if (value instanceof List)
    {
        List<String> items = (List<String>) value;
        for (String item : items)
        {
            output.write("<value>");
            output.write(escapeXML(item));
            output.write("</value>\n");
        }
    }

    String rt = getRichText();
    if (rt != null)
    {
        output.write("<value-richtext>");
        output.write(escapeXML(rt));
        output.write("</value-richtext>\n");
    }
    List<FDFField> kids = getKids();
    if (kids != null)
    {
        for (FDFField kid : kids)
        {
            kid.writeXML(output);
        }
    }
    output.write("</field>\n");
}

public COSBase getCOSValue() throws IOException
{
    COSBase value = field.getDictionaryObject(COSName.V);
    if (value instanceof COSName //
            || value instanceof COSArray //
            || value instanceof COSString //
            || value instanceof COSStream)
    {
        return value;
    }
    if (value != null)
    {
        throw new IOException("Error: Unknown type for field import: " + value);
    }
    return null;
}

public List<FDFField> getKids()
{
    COSArray kids = field.getCOSArray(COSName.KIDS);
    if (kids != null)
    {
        List<FDFField> actuals = new ArrayList<>(kids.size());
        for (int i = 0; i < kids.size(); i++)
        {
            actuals.add(new FDFField((COSDictionary) kids.getObject(i)));
        }
        return new COSArrayList<>(actuals, kids);
    }
    return null;
}

public List<Object> getOptions()
{
    COSArray array = field.getCOSArray(COSName.OPT);
    if (array != null)
    {
        List<Object> objects = new ArrayList<>(array.size());
        for (int i = 0; i < array.size(); i++)
        {
            COSBase next = array.getObject(i);
            if (next instanceof COSString)
            {
                objects.add(((COSString) next).getString());
            }
            else
            {
                COSArray value = (COSArray) next;
                objects.add(new FDFOptionElement(value));
            }
        }
        return new COSArrayList<>(objects, array);
    }
    return null;
}

public String getRichText()
{
    COSBase rv = field.getDictionaryObject(COSName.RV);
    if (rv == null)
    {
        return null;
    }
    else if (rv instanceof COSString)
    {
        return ((COSString) rv).getString();
    }
    else
    {
        return ((COSStream) rv).toTextString();
    }
}

public Object getValue() throws IOException
{
    COSBase value = field.getDictionaryObject(COSName.V);
    if (value instanceof COSName)
    {
        return ((COSName) value).getName();
    }
    else if (value instanceof COSArray)
    {
        return ((COSArray) value).toCOSStringStringList();
    }
    else if (value instanceof COSString)
    {
        return ((COSString) value).getString();
    }
    else if (value instanceof COSStream)
    {
        return ((COSStream) value).toTextString();
    }
    else if (value != null)
    {
        throw new IOException("Error: Unknown type for field import: " + value);
    }
    else
    {
        return null;
    }
}

public void setValue(Object value) throws IOException
{
    COSBase cos = null;
    if (value instanceof List)
    {
        cos = COSArray.ofCOSStrings((List<String>) value);
    }
    else if (value instanceof String)
    {
        cos = new COSString((String) value);
    }
    else if (value instanceof COSObjectable)
    {
        cos = ((COSObjectable) value).getCOSObject();
    }
    else if (value != null)
    {
        throw new IOException("Error: Unknown type for field import: " + value);
    }
    field.setItem(COSName.V, cos);
}

public PDGraphicsState clone()
{
    try
    {
        PDGraphicsState clone = (PDGraphicsState)super.clone();
        clone.textState = textState.clone();
        clone.currentTransformationMatrix = currentTransformationMatrix.clone();
        clone.strokingColor = strokingColor; // immutable
        clone.nonStrokingColor = nonStrokingColor; // immutable
        clone.lineDashPattern = lineDashPattern; // immutable
        clone.clippingPaths = clippingPaths; // not cloned, see intersectClippingPath
        clone.clippingPathCache = clippingPathCache;
        clone.isClippingPathDirty = false;
        clone.textLineMatrix = textLineMatrix == null ? null : textLineMatrix.clone();
        clone.textMatrix = textMatrix == null ? null : textMatrix.clone();
        return clone;
    }
    catch (CloneNotSupportedException e)
    {
        // should not happen
        throw new RuntimeException(e);
    }
}

public void getIndirectObjectKeys(Collection<COSObjectKey> indirectObjects)
{
    if (indirectObjects == null)
    {
        return;
    }
    COSObjectKey key = getKey();
    if (key != null)
    {
        // avoid endless recursions
        if (indirectObjects.contains(key))
        {
            return;
        }
        else
        {
            indirectObjects.add(key);
        }
    }

    for (COSBase cosBase : objects)
    {
        if (cosBase == null)
        {
            continue;
        }
        COSObjectKey cosBaseKey = cosBase.getKey();
        if (cosBaseKey != null && indirectObjects.contains(cosBaseKey))
        {
            continue;
        }
        if (cosBase instanceof COSObject)
        {
            // dereference object
            cosBase = ((COSObject) cosBase).getObject();
        }
        if (cosBase instanceof COSDictionary)
        {
            // descend to included dictionary to collect all included indirect objects
            ((COSDictionary) cosBase).getIndirectObjectKeys(indirectObjects);
        }
        else if (cosBase instanceof COSArray)
        {
            // descend to included array to collect all included indirect objects
            ((COSArray) cosBase).getIndirectObjectKeys(indirectObjects);
        }
        else if (cosBaseKey != null)
        {
            // add key for all indirect objects other than COSDictionary/COSArray
            indirectObjects.add(cosBaseKey);
        }
    }
}

