public int indexOf(COSBase object)
{
    for (int i = 0; i < size(); i++)
    {
        COSBase item = get(i);
        if (item == null)
        {
            if (object == null)
            {
                return i;
            }
        }
        else if (item.equals(object))
        {
            return i;
        }
    }
    return -1;
}

