public void extractRegions( PDPage page ) throws IOException
{
    for (String regionName : regions)
    {
        setStartPage(getCurrentPageNo());
        setEndPage(getCurrentPageNo());
        // reset the stored text for the region so this class can be reused.
        ArrayList<List<TextPosition>> regionCharactersByArticle = new ArrayList<>();
        regionCharactersByArticle.add(new ArrayList<>());
        regionCharacterList.put( regionName, regionCharactersByArticle );
        regionText.put( regionName, new StringWriter() );
    }

    if( page.hasContents() )
    {
        processPage( page );
    }
}

public void processPage(PDPage page) throws IOException
{
    if (currentPageNo >= startPage && currentPageNo <= endPage
            && (startBookmarkPageNumber == -1 || currentPageNo >= startBookmarkPageNumber)
            && (endBookmarkPageNumber == -1 || currentPageNo <= endBookmarkPageNumber))
    {
        startPage(page);

        int numberOfArticleSections = 1;
        if (shouldSeparateByBeads)
        {
            fillBeadRectangles(page);
            numberOfArticleSections += beadRectangles.size() * 2;
        }
        int originalSize = charactersByArticle.size();
        charactersByArticle.ensureCapacity(numberOfArticleSections);
        int lastIndex = Math.max(numberOfArticleSections, originalSize);
        for (int i = 0; i < lastIndex; i++)
        {
            if (i < originalSize)
            {
                charactersByArticle.get(i).clear();
            }
            else
            {
                if (numberOfArticleSections < originalSize)
                {
                    //TODO Looks like decrement (--i) needed because next value will be ignored.
                    // This segment is never reached in tests?!
                    charactersByArticle.remove(i);
                }
                else
                {
                    charactersByArticle.add(new ArrayList<>());
                }
            }
        }
        characterListMapping.clear();
        super.processPage(page);
        writePage();
        endPage(page);
        page.removePageResourceFromCache();
    }
}

public int compareTo(XReferenceEntry xReferenceEntry)
{
    if (getReferencedKey() == null)
    {
        return -1;
    }
    else if (xReferenceEntry == null || xReferenceEntry.getReferencedKey() == null)
    {
        return 1;
    }

    return getReferencedKey().compareTo(xReferenceEntry.getReferencedKey());
}

public COSName getKeyForValue(Object value)
{
    for (Map.Entry<COSName, COSBase> entry : items.entrySet())
    {
        Object nextValue = entry.getValue();
        if (nextValue.equals(value)
                || (nextValue instanceof COSObject && ((COSObject) nextValue).getObject()
                        .equals(value)))
        {
            return entry.getKey();
        }
    }
    return null;
}

public COSFloat( String aFloat ) throws IOException
{
    float parsedValue;
    String stringValue = null;
    try
    {
        float f = Float.parseFloat(aFloat);
        parsedValue = coerce(f);
        stringValue = f == parsedValue ? aFloat : null;
    }
    catch( NumberFormatException e )
    {
        if (aFloat.startsWith("--"))
        {
            // PDFBOX-4289 has --16.33
            aFloat = aFloat.substring(1);
        }
        else if (aFloat.matches("^0\\.0*-\\d+"))
        {
            // PDFBOX-2990 has 0.00000-33917698
            // PDFBOX-3369 has 0.00-35095424
            // PDFBOX-3500 has 0.-262
            aFloat = "-" + aFloat.replaceFirst("-", "");
        }
        else if (aFloat.matches("^-\\d+\\.-\\d+"))
        {
            // PDFBOX-5829 has -12.-1
            aFloat = "-" + aFloat.replace("-", "");
        }
        else
        {
            throw new IOException("Error expected floating point number actual='" + aFloat + "'", e);
        }

        try
        {
            parsedValue = coerce(Float.parseFloat(aFloat));
        }
        catch (NumberFormatException e2)
        {
            throw new IOException("Error expected floating point number actual='" + aFloat + "'", e2);
        }
    }
    value = parsedValue;
    valueAsString = stringValue;
}

public void endMarkedContentSequence()
{
    PDMarkedContent markedContent = currentMarkedContents.peek();
