}

public List<PDThreadBead> getThreadBeads()
{
    COSArray beads = page.getCOSArray(COSName.B);
    if (beads == null)
    {
        beads = new COSArray();
    }
    List<PDThreadBead> pdObjects = new ArrayList<>(beads.size());
    for (int i = 0; i < beads.size(); i++)
    {
        COSBase base = beads.getObject(i);
        PDThreadBead bead = null;
        // in some cases the bead is null
        if (base instanceof COSDictionary)
        {
            bead = new PDThreadBead((COSDictionary) base);
        }
        pdObjects.add(bead);
    }
    return new COSArrayList<>(pdObjects, beads);
}

public PDPage findDestinationPage(PDDocument doc) throws IOException
{
    PDDestination dest = getDestination();
    if (dest == null)
    {
        PDAction outlineAction = getAction();
        if (outlineAction instanceof PDActionGoTo)
        {
            dest = ((PDActionGoTo) outlineAction).getDestination();
        }
    }
    if (dest == null)
    {
        return null;
    }

    PDPageDestination pageDestination = null;
    if (dest instanceof PDNamedDestination)
    {
        pageDestination = doc.getDocumentCatalog().findNamedDestinationPage((PDNamedDestination) dest);
        if (pageDestination == null)
        {
            return null;
        }
    }
    else if (dest instanceof PDPageDestination)
    {
        pageDestination = (PDPageDestination) dest;
    }
    else
    {
        throw new IOException("Error: Unknown destination type " + dest);
    }

    PDPage page = pageDestination.getPage();
    if (page == null)
    {
        // Malformed PDF: local destinations must have a page object,
        // not a page number, these are meant for remote destinations.
        int pageNumber = pageDestination.getPageNumber();
        if (pageNumber != -1)
        {
            page = doc.getPage(pageNumber);
        }
    }
    return page;
}

public float getWidth(int code) throws IOException
{
    int firstChar = dict.getInt(COSName.FIRST_CHAR, -1);
    int lastChar = dict.getInt(COSName.LAST_CHAR, -1);
    List<Float> widths = getWidths();
    if (!widths.isEmpty() && code >= firstChar && code <= lastChar)
    {
        if (code - firstChar >= widths.size())
        {
            return 0;
        }
        Float w = widths.get(code - firstChar);
        return w == null ? 0 : w;
    }
    else
    {
        PDFontDescriptor fd = getFontDescriptor();
        if (fd != null)
        {
            return fd.getMissingWidth();
        }
        else
        {
            return getWidthFromFont(code);
        }
    }
}

public float getWidth(int code) throws IOException
{
    Float width = codeToWidthMap.get(code);
    if (width != null)
    {
        return width;
    }

    // Acrobat overrides the widths in the font program on the conforming reader's system with
    // the widths specified in the font dictionary." (Adobe Supplement to the ISO 32000)
    //
    // Note: The Adobe Supplement says that the override happens "If the font program is not
    // embedded", however PDFBOX-427 shows that it also applies to embedded fonts.

    // Type1, Type1C, Type3
    if (dict.getDictionaryObject(COSName.WIDTHS) != null
            || dict.containsKey(COSName.MISSING_WIDTH))
    {
        int firstChar = dict.getInt(COSName.FIRST_CHAR, -1);
        int lastChar = dict.getInt(COSName.LAST_CHAR, -1);
        int siz = getWidths().size();
        int idx = code - firstChar;
        if (siz > 0 && code >= firstChar && code <= lastChar && idx < siz)
        {
            width = getWidths().get(idx);
            if (width == null)
            {
                width = 0f;
            }
            codeToWidthMap.put(code, width);
            return width;
        }

        PDFontDescriptor fd = getFontDescriptor();
        if (fd != null)
        {
            // get entry from /MissingWidth entry
            width = fd.getMissingWidth();
            codeToWidthMap.put(code, width);
            return width;
        }
    }

    // standard 14 font widths are specified by an AFM
    if (isStandard14())
    {
        width = getStandard14Width(code);
        codeToWidthMap.put(code, width);
        return width;
    }

    // if there's nothing to override with, then obviously we fall back to the font
    width = getWidthFromFont(code);
    codeToWidthMap.put(code, width);
    return width;
}

public DictionaryEncoding(COSDictionary fontEncoding)
{
    encoding = fontEncoding;
    COSName name = encoding.getCOSName(COSName.BASE_ENCODING);
    if (name != null)
    {
        baseEncoding = Encoding.getInstance(name); // null when the name is invalid
        if (baseEncoding != null)
        {
            // PDFBOX-5963
            // PDF Specification: "Differences array shall specify the complete character
            // encoding for this font" but other viewers read it, thus we do too.
            LOG.warn("/BaseEncoding in type 3 font");
            codeToName.putAll(baseEncoding.codeToName);
            inverted.putAll(baseEncoding.inverted);
        }
    }
    else
    {
        baseEncoding = null;
    }
    applyDifferences();
}

public COSDictionary getLinearizedDictionary()
{
    // get all keys with a positive offset in ascending order, as the linearization dictionary shall be the first
    // within the pdf
    List<COSObjectKey> objectKeys = xrefTable.entrySet().stream() //
            .filter(e -> e.getValue() > 0L) //
            .sorted(Entry.comparingByValue()) //
            .map(Entry::getKey) //
            .collect(Collectors.toList());
    for (COSObjectKey objectKey : objectKeys)
    {
        COSObject objectFromPool = getObjectFromPool(objectKey);
        COSBase realObject = objectFromPool.getObject();
        if (realObject instanceof COSDictionary)
        {
            COSDictionary dic = (COSDictionary) realObject;
            if (dic.getItem(COSName.LINEARIZED) != null)
            {
                return dic;
            }
        }
    }
    return null;
}

public List<PDAnnotation> getAnnotations(AnnotationFilter annotationFilter) throws IOException
{
    COSArray annots = page.getCOSArray(COSName.ANNOTS);
    if (annots == null)
    {
        return new COSArrayList<>(page, COSName.ANNOTS);
    }

    List<PDAnnotation> actuals = new ArrayList<>();
    for (int i = 0; i < annots.size(); i++)
    {
        COSBase item = annots.getObject(i);
        if (item == null)
        {
            continue;
        }
        PDAnnotation createdAnnotation = PDAnnotation.createAnnotation(item);
        if (annotationFilter.accept(createdAnnotation))
        {
            actuals.add(createdAnnotation);
        }
    }
    return new COSArrayList<>(actuals, annots);
}

public Iterator<PDStream> getContentStreams()
{
    List<PDStream> streams = new ArrayList<>();
    COSBase base = page.getDictionaryObject(COSName.CONTENTS);
    if (base instanceof COSStream)
    {
        streams.add(new PDStream((COSStream) base));
    }
    else if (base instanceof COSArray)
    {
        COSArray array = (COSArray)base;
        for (int i = 0; i < array.size(); i++)
        {
            COSStream stream = (COSStream) array.getObject(i);
            streams.add(new PDStream(stream));
        }
    }
    return streams.iterator();
}

public RandomAccessRead getContentsForRandomAccess() throws IOException
{
    COSStream contentStream = page.getCOSStream(COSName.CONTENTS);
    if (contentStream != null)
    {
        try
        {
            return contentStream.createView();
        }
        catch (IOException exception)
        {
            LOG.warn("skipped malformed content stream");
            return new RandomAccessReadBuffer(DELIMITER);
        }
    }
    COSArray array = page.getCOSArray(COSName.CONTENTS);
    if (array != null)
    {
        List<COSStream> streams = array.toList().stream() //
                .map(o -> o instanceof COSObject ? ((COSObject) o).getObject() : o) //
                .filter(COSStream.class::isInstance) //
                .map(b -> (COSStream) b) //
                .collect(Collectors.toList());
        List<RandomAccessRead> inputStreams = new ArrayList<>();
        streams.forEach(stream ->
        {
            try
            {
                inputStreams.add(stream.createView());
                inputStreams.add(new RandomAccessReadBuffer(DELIMITER));
            }
            catch (IOException exception)
            {
                LOG.warn("malformed substream of content stream skipped");
            }
        });
        if (!inputStreams.isEmpty())
        {
            return new SequenceRandomAccessRead(inputStreams);
        }
    }
    return new RandomAccessReadBuffer(new byte[0]);
}

public RandomAccessRead getContentsForStreamParsing() throws IOException
{
    // return a stream based reader if there is just one stream
    COSStream contentStream = page.getCOSStream(COSName.CONTENTS);
    if (contentStream != null)
    {
        COSBase filter = contentStream.getFilters();
        // for now only streams using a flate filter are supported
        if (filter instanceof COSName && ((COSName) filter).equals(COSName.FLATE_DECODE))
        {
            try
            {
                FlateFilterDecoderStream decoderStream = new FlateFilterDecoderStream(
                        contentStream.createRawInputStream());
                return new NonSeekableRandomAccessReadInputStream(decoderStream);
            }
            catch (IOException exception)
            {
                LOG.warn("skipped malformed content stream");
                return new RandomAccessReadBuffer(DELIMITER);
            }
        }
    }
    return getContentsForRandomAccess();
}

public List<PDViewportDictionary> getViewports()
{
    COSArray array = page.getCOSArray(COSName.VP);
    if (array == null)
