public void insertAfter(PDPage newPage, PDPage prevPage)
{
    COSDictionary prevPageDict = prevPage.getCOSObject();
    COSDictionary parentDict = prevPageDict.getCOSDictionary(COSName.PARENT, COSName.P);
    COSArray kids = parentDict.getCOSArray(COSName.KIDS);
    boolean found = false;
    for (int i = 0; i < kids.size(); ++i)
    {
        COSDictionary pageDict = (COSDictionary) kids.getObject(i);
        if (pageDict == prevPage.getCOSObject())
        {
            kids.add(i + 1, newPage.getCOSObject());
            newPage.getCOSObject().setItem(COSName.PARENT, parentDict);
            found = true;
            break;
        }
    }
    if (!found)
    {
        throw new IllegalArgumentException("attempted to insert before orphan page");
    }
    increaseParents(parentDict);
}

public void insertBefore(PDPage newPage, PDPage nextPage)
{
    COSDictionary nextPageDict = nextPage.getCOSObject();
    COSDictionary parentDict = nextPageDict.getCOSDictionary(COSName.PARENT, COSName.P);
    COSArray kids = parentDict.getCOSArray(COSName.KIDS);
    boolean found = false;
    for (int i = 0; i < kids.size(); ++i)
    {
        COSDictionary pageDict = (COSDictionary) kids.getObject(i);
        if (pageDict == nextPage.getCOSObject())
        {
            kids.add(i, newPage.getCOSObject());
            newPage.getCOSObject().setItem(COSName.PARENT, parentDict);
            found = true;
            break;
        }
    }
    if (!found)
    {
        throw new IllegalArgumentException("attempted to insert before orphan page");
    }
    increaseParents(parentDict);
}

public float getSpaceWidth()
{
    if (Float.compare(fontWidthOfSpace, -1f) == 0)
    {
        try
        {
            if (toUnicodeCMap != null && dict.containsKey(COSName.TO_UNICODE))
            {
                int spaceMapping = toUnicodeCMap.getSpaceMapping();
                if (spaceMapping > -1)
                {
                    fontWidthOfSpace = getWidth(spaceMapping);
                }
            }
            else
            {
                try
                {
                    // PDFBOX-5920: try with encoding, which gets the correct code
                    fontWidthOfSpace = getStringWidth(" ");
                }
                catch (IllegalArgumentException | UnsupportedOperationException ex)
                {
                    // Happens if space is not available in the font
                    // or if encoding isn't implemented
                    LOG.debug(ex.getMessage(), ex);
                }
                if (fontWidthOfSpace <= 0)
                {
                    fontWidthOfSpace = getWidth(32);
                }
            }

            // try to get it from the font itself
            if (fontWidthOfSpace <= 0)
            {
                fontWidthOfSpace = getWidthFromFont(32);
                // use the average font width as fall back
                if (fontWidthOfSpace <= 0)
                {
                    fontWidthOfSpace = getAverageFontWidth();
                }
            }
        }
        catch (Exception e)
        {
            LOG.error("Can't determine the width of the space character for font " +
                    getName() + ", assuming 250", e);
            fontWidthOfSpace = 250f;
        }
        if (LOG.isDebugEnabled())
        {
            LOG.debug("Space width for font " + getName() + " is " + fontWidthOfSpace);
        }
    }
    return fontWidthOfSpace;
}

public String getTag(Map<Integer, Integer> gidToCid)
{
    // deterministic
    long num = gidToCid.hashCode();

    // base25 encode
    StringBuilder sb = new StringBuilder();
    do
    {
        long div = num / 25;
        int mod = (int)(num % 25);
        sb.append(BASE25.charAt(mod));
        num = div;
    } while (num != 0 && sb.length() < 6);

    // pad
    while (sb.length() < 6)
    {
        sb.insert(0, 'A');
    }

    sb.append('+');
    return sb.toString();
}

