public int codeToGID(int code) throws IOException
{
    extractCmapTable();
    int gid = 0;

    if (!isSymbolic()) // non-symbolic
    {
        String name = encoding.getName(code);
        if (".notdef".equals(name))
        {
            return 0;
        }
        else
        {
            // (3, 1) - (Windows, Unicode)
            if (cmapWinUnicode != null)
            {
                String unicode = GlyphList.getAdobeGlyphList().toUnicode(name);
                if (unicode != null)
                {
                    int uni = unicode.codePointAt(0);
                    gid = cmapWinUnicode.getGlyphId(uni);
                }
            }

            // (1, 0) - (Macintosh, Roman)
            if (gid == 0 && cmapMacRoman != null)
            {
                Integer macCode = INVERTED_MACOS_ROMAN.get(name);
                if (macCode != null)
                {
                    gid = cmapMacRoman.getGlyphId(macCode);
                }
            }

            // 'post' table
            if (gid == 0)
            {
                gid = ttf.nameToGID(name);
            }
        }
    }
    else // symbolic
    {
        // PDFBOX-4755 / PDF.js #5501
        // PDFBOX-3965: fallback for font has that the symbol flag but isn't
        if (cmapWinUnicode != null)
        {
            if (encoding instanceof WinAnsiEncoding || encoding instanceof MacRomanEncoding)
            {
                String name = encoding.getName(code);
                if (".notdef".equals(name))
                {
                    return 0;
                }
                String unicode = GlyphList.getAdobeGlyphList().toUnicode(name);
                if (unicode != null)
                {
                    int uni = unicode.codePointAt(0);
                    gid = cmapWinUnicode.getGlyphId(uni);
                }
            }
            else
            {
                gid = cmapWinUnicode.getGlyphId(code);
            }
        }

        // (3, 0) - (Windows, Symbol)
        if (gid == 0 && cmapWinSymbol != null)
        {
            gid = cmapWinSymbol.getGlyphId(code);
            if (code >= 0 && code <= 0xFF)
            {
                // the CMap may use one of the following code ranges,
                // so that we have to add the high byte to get the
                // mapped value
                if (gid == 0)
                {
                    // F000 - F0FF
                    gid = cmapWinSymbol.getGlyphId(code + START_RANGE_F000);
                }
                if (gid == 0)
                {
                    // F100 - F1FF
                    gid = cmapWinSymbol.getGlyphId(code + START_RANGE_F100);
                }
                if (gid == 0)
                {
                    // F200 - F2FF
                    gid = cmapWinSymbol.getGlyphId(code + START_RANGE_F200);
                }
            }
        }

        // (1, 0) - (Mac, Roman)
        if (gid == 0 && cmapMacRoman != null)
        {
            gid = cmapMacRoman.getGlyphId(code);
        }
    }

    return gid;
}

public int getColorSpaceType()
{
    if (iccProfile != null)
    {
        return iccProfile.getColorSpaceType();
    }

    // if the ICC Profile could not be read
    switch (alternateColorSpace.getNumberOfComponents())
    {
        case 1:
            return ColorSpace.TYPE_GRAY;
        case 3:
            return ColorSpace.TYPE_RGB;
        case 4:
            return ColorSpace.TYPE_CMYK;
        default:
            // should not happen as all ICC color spaces in PDF must have 1,3, or 4 components
            return -1;
    }
}

public float[] getDefaultDecode(int bitsPerComponent)
{
    if (awtColorSpace != null)
    {
        int n = getNumberOfComponents();
        float[] decode = new float[n * 2];
        for (int i = 0; i < n; i++)
        {
            decode[i * 2] = awtColorSpace.getMinValue(i);
            decode[i * 2 + 1] = awtColorSpace.getMaxValue(i);
        }
        return decode;
    }
    else
    {
        return alternateColorSpace.getDefaultDecode(bitsPerComponent);
    }
}

public int getNumberOfComponents()
{
    if (numberOfComponents < 0)
    {
        numberOfComponents = stream.getCOSObject().getInt(COSName.N);

        // PDFBOX-4801 correct wrong /N values
        if (iccProfile != null)
        {
            int numIccComponents = iccProfile.getNumComponents();
            if (numIccComponents != numberOfComponents)
            {
                LOG.warn("Using " + numIccComponents + " components from ICC profile info instead of " +
                        numberOfComponents + " components from /N entry");
                numberOfComponents = numIccComponents;
            }
        }
    }
    return numberOfComponents;
}

public void setRangeForComponent(PDRange range, int n)
{
    COSArray rangeArray = stream.getCOSObject().getCOSArray(COSName.RANGE);
    if (rangeArray == null)
    {
        rangeArray = new COSArray();
        stream.getCOSObject().setItem(COSName.RANGE, rangeArray);
    }
    // extend range array with default values if needed
    while (rangeArray.size() < (n + 1) * 2)
    {
        rangeArray.add(COSFloat.ZERO);
        rangeArray.add(COSFloat.ONE);
    }
    rangeArray.set(n*2, new COSFloat(range.getMin()));
    rangeArray.set(n*2+1, new COSFloat(range.getMax()));
}

public float[] toRGB(float[] value) throws IOException
{
    if (isRGB)
    {
