    {
        getParent().setFirstChild(newSibling);
    }
    updateParentOpenCountForAddedChild(newSibling);
}

public boolean hasNext()
{
    if (startingItem == null)
    {
        return false;
    }
    if (currentItem == null)
    {
        return true;
    }
    PDOutlineItem sibling = currentItem.getNextSibling();
    return sibling != null && !startingItem.equals(sibling);
}

public PDOutlineItem next()
{
    if (!hasNext())
    {
        throw new NoSuchElementException();
    }
    if (currentItem == null)
    {
        currentItem = startingItem;
    }
    else
    {
        currentItem = currentItem.getNextSibling();
    }
    return currentItem;
}

