public void doWriteObject(COSObjectKey key, COSBase obj) throws IOException
{
    // don't write missing objects to avoid broken xref tables
    if (obj == null || (obj instanceof COSObject && ((COSObject) obj).getObject() == null))
    {
        return;
    }
    // add a x ref entry
    addXRefEntry(new NormalXReference(getStandardOutput().getPos(), key, obj));
    // write the object
    getStandardOutput()
            .write(String.valueOf(key.getNumber()).getBytes(StandardCharsets.ISO_8859_1));
    getStandardOutput().write(SPACE);
    getStandardOutput()
            .write(String.valueOf(key.getGeneration()).getBytes(StandardCharsets.ISO_8859_1));
    getStandardOutput().write(SPACE);
    getStandardOutput().write(OBJ);
    getStandardOutput().writeEOL();
    obj.accept(this);
    getStandardOutput().writeEOL();
    getStandardOutput().write(ENDOBJ);
    getStandardOutput().writeEOL();
}

public void visitFromArray(COSArray array) throws IOException
{
    int count = 0;
    getStandardOutput().write(ARRAY_OPEN);
    for (Iterator<COSBase> i = array.iterator(); i.hasNext();)
    {
        COSBase current = i.next();
        if( current instanceof COSDictionary )
        {
            writeDictionary((COSDictionary) current);
        }
        else if (current instanceof COSArray)
        {
            writeArray((COSArray) current);
        }
        else if( current instanceof COSObject )
        {
            addObjectToWrite(current);
            writeReference(current);
        }
        else if( current == null )
        {
            COSNull.NULL.accept( this );
        }
        else
        {
            current.accept(this);
        }
        count++;
        if (i.hasNext())
        {
            if (count % 10 == 0)
            {
                getStandardOutput().writeEOL();
            }
            else
            {
                getStandardOutput().write(SPACE);
            }
        }
    }
    getStandardOutput().write(ARRAY_CLOSE);
    getStandardOutput().writeEOL();
}

public void visitFromDictionary(COSDictionary obj) throws IOException
{
    detectPossibleSignature(obj);
    getStandardOutput().write(DICT_OPEN);
    getStandardOutput().writeEOL();
    for (Map.Entry<COSName, COSBase> entry : obj.entrySet())
    {
        COSBase value = entry.getValue();
        if (value != null)
        {
            entry.getKey().accept(this);
            getStandardOutput().write(SPACE);
            if( value instanceof COSDictionary )
            {
                COSDictionary dict = (COSDictionary)value;

                if (!incrementalUpdate)
                {            
                    // write all XObjects as direct objects, this will save some size
                    // PDFBOX-3684: but avoid dictionary that references itself
                    COSBase item = dict.getItem(COSName.XOBJECT);
                    if (item != null && !COSName.XOBJECT.equals(entry.getKey()))
                    {
                        item.setDirect(true);
                    }
                    item = dict.getItem(COSName.RESOURCES);
                    if (item != null && !COSName.RESOURCES.equals(entry.getKey()))
                    {
                        item.setDirect(true);
                    }
                }
                writeDictionary(dict);
            }
            else if( value instanceof COSObject )
            {
                addObjectToWrite(value);
                writeReference(value);
            }
            else
            {
                // If we reach the pdf signature, we need to determinate the position of the
                // content and byterange
                if(reachedSignature && COSName.CONTENTS.equals(entry.getKey()))
                {
                    signatureOffset = getStandardOutput().getPos();
                    value.accept(this);
                    signatureLength = getStandardOutput().getPos()- signatureOffset;
                }
                else if(reachedSignature && COSName.BYTERANGE.equals(entry.getKey()))
                {
                    byteRangeArray = (COSArray) entry.getValue();
                    byteRangeOffset = getStandardOutput().getPos() + 1;
                    value.accept(this);
                    byteRangeLength = getStandardOutput().getPos() - 1 - byteRangeOffset;
                    reachedSignature = false;
                }
                else if (value instanceof COSArray)
                {
                    writeArray((COSArray) value);
                }
                else
                {
                    value.accept(this);
                }
            }
            getStandardOutput().writeEOL();

        }
        else
        {
            //then we won't write anything, there are a couple cases
            //were the value of an entry in the COSDictionary will
            //be a dangling reference that points to nothing
            //so we will just not write out the entry if that is the case
        }
    }
    getStandardOutput().write(DICT_CLOSE);
    getStandardOutput().writeEOL();
}

public void visitFromDocument(COSDocument doc) throws IOException
{
    if(!incrementalUpdate)
    {
        doWriteHeader(doc);
    }
    else
    {
        // Sometimes the original file will be missing a newline at the end
        // In order to avoid having %%EOF the first object on the same line
        // as the %%EOF, we put a newline here. If there's already one at
        // the end of the file, an extra one won't hurt. PDFBOX-1051
        getStandardOutput().writeCRLF();
    }

    if (isCompress())
    {
        doWriteBodyCompressed(doc);
    }
    else
    {
        doWriteBody(doc);
    }

    if(incrementalUpdate || doc.isXRefStream())
    {
        doWriteXRefInc(doc);
    }
    else
    {
        doWriteXRefTable();
        doWriteTrailer(doc);
    }

    // write endof
    getStandardOutput().write(STARTXREF);
    getStandardOutput().writeEOL();
    getStandardOutput().write(String.valueOf(getStartxref()).getBytes(StandardCharsets.ISO_8859_1));
    getStandardOutput().writeEOL();
    getStandardOutput().write(EOF);
    getStandardOutput().writeEOL();

    if (incrementalUpdate)
    {
        if (signatureOffset == 0 || byteRangeOffset == 0)
        {
            doWriteIncrement();
        }
        else
        {
            doWriteSignature();
        }
    }

}

public void visitFromStream(COSStream obj) throws IOException
{
    if (willEncrypt)
    {
        pdDocument.getEncryption().getSecurityHandler()
            .encryptStream(obj, currentObjectKey.getNumber(), currentObjectKey.getGeneration());
    }

    InputStream input = null;
    try
    {
        // write the stream content
        visitFromDictionary(obj);
        getStandardOutput().write(STREAM);
        getStandardOutput().writeCRLF();
        if (obj.hasData())
        {
            input = obj.createRawInputStream();
            IOUtils.copy(input, getStandardOutput());
        }
        getStandardOutput().writeCRLF();
        getStandardOutput().write(ENDSTREAM);
        getStandardOutput().writeEOL();
    }
    finally
    {
        if (input != null)
        {
            input.close();
        }
    }
}

public DecodeResult decode(InputStream encoded, OutputStream decoded,
                           COSDictionary parameters, int index) throws IOException
{
    return decode(encoded, decoded, parameters, index, DecodeOptions.DEFAULT);
}

public String toString()
{
    StringBuilder sb = new StringBuilder();
    for (float f : color)
    {
        if (sb.length() > 0)
        {
            sb.append(' ');
        }
        sb.append(String.format("%3.2f", f));
    }
    return "Vertex{ " + point + ", colors=[" + sb + "] }";
}

public List<PDField> getChildren()
{
    //TODO: why not return a COSArrayList like in PDPage.getAnnotations() ?

    List<PDField> children = new ArrayList<>();
    COSArray kids = getCOSObject().getCOSArray(COSName.KIDS);
    if (kids == null)
    {
        return children;
    }
    for (int i = 0; i < kids.size(); i++)
    {
        COSBase kid = kids.getObject(i);
        if (kid instanceof COSDictionary)
        {
            if (kid.getCOSObject() == this.getCOSObject())
            {
                LOG.warn("Child field is same object as parent");
                continue;
            }
            PDField field = PDField.fromDictionary(getAcroForm(), (COSDictionary) kid, this);
            if (field != null)
            {
                children.add(field);
            }
        }
    }
    return children;
}

public boolean add(E o)
{
    //when adding if there is a parentDict then change the item
    //in the dictionary from a single item to an array.
    if( parentDict != null )
    {
        parentDict.setItem( dictKey, array );
        //clear the parent dict so it doesn't happen again, there might be
        //a usecase for keeping the parentDict around but not now.
        parentDict = null;
    }
    //string is a special case because we can't subclass to be COSObjectable
    if( o instanceof String )
    {
        array.add( new COSString( (String)o ) );
    }
    else
    {
        if(array != null)
        {
            array.add(((COSObjectable)o).getCOSObject());
        }
    }
    return actual.add(o);
}

public void add(int index, E element)
{
    if (isFiltered) {
        throw new UnsupportedOperationException("Adding an element in a filtered List is not permitted");
    }

    //when adding if there is a parentDict then change the item
    //in the dictionary from a single item to an array.
    if( parentDict != null )
    {
        parentDict.setItem( dictKey, array );
        //clear the parent dict so it doesn't happen again, there might be
        //a usecase for keeping the parentDict around but not now.
        parentDict = null;
    }
    actual.add( index, element );
    if( element instanceof String )
    {
        array.add( index, new COSString( (String)element ) );
    }
    else
    {
        array.add( index, ((COSObjectable)element).getCOSObject() );
    }
}

public boolean addAll(Collection<? extends E> c)
{
    if (isFiltered) {
        throw new UnsupportedOperationException("Adding to a filtered List is not permitted");
    }

    //when adding if there is a parentDict then change the item
    //in the dictionary from a single item to an array.
    if( parentDict != null && c.size() > 0)
    {
        parentDict.setItem( dictKey, array );
        //clear the parent dict so it doesn't happen again, there might be
        //a usecase for keeping the parentDict around but not now.
        parentDict = null;
    }
    array.addAll( toCOSObjectList( c ) );
    return actual.addAll( c );
}

public boolean addAll(int index, Collection<? extends E> c)
{
    if (isFiltered) {
        throw new UnsupportedOperationException("Inserting to a filtered List is not permitted");
    }

    //when adding if there is a parentDict then change the item
    //in the dictionary from a single item to an array.
    if( parentDict != null && c.size() > 0)
    {
        parentDict.setItem( dictKey, array );
        //clear the parent dict so it doesn't happen again, there might be
        //a usecase for keeping the parentDict around but not now.
        parentDict = null;
    }

    array.addAll( index, toCOSObjectList( c ) );
    return actual.addAll( index, c );
}

public boolean remove(Object o)
{

    if (isFiltered) {
        throw new UnsupportedOperationException("removing entries from a filtered List is not permitted");
    }

    boolean retval = true;
    int index = actual.indexOf( o );
    if( index >= 0 )
    {
        actual.remove( index );
        array.remove( index );
    }
    else
    {
        retval = false;
    }
    return retval;
}

public E set(int index, E element)
{
    if (isFiltered) {
        throw new UnsupportedOperationException("Replacing an element in a filtered List is not permitted");
    }

    if( element instanceof String )
    {
        COSString item = new COSString( (String)element );
        if( parentDict != null && index == 0 )
        {
            parentDict.setItem( dictKey, item );
        }
        array.set( index, item );
    }
    else
    {
        if( parentDict != null && index == 0 )
        {
            parentDict.setItem( dictKey, ((COSObjectable)element).getCOSObject() );
        }
        array.set( index, ((COSObjectable)element).getCOSObject() );
    }
    return actual.set( index, element );
}

public DictionaryEncoding(COSName baseEncoding, COSArray differences)
{
    encoding = new COSDictionary();
    encoding.setItem(COSName.NAME, COSName.ENCODING);
    encoding.setItem(COSName.DIFFERENCES, differences);
    if (baseEncoding != COSName.STANDARD_ENCODING)
    {
        encoding.setItem(COSName.BASE_ENCODING, baseEncoding);
        this.baseEncoding = Encoding.getInstance(baseEncoding);
    }
    else
    {
        this.baseEncoding = Encoding.getInstance(baseEncoding);
    }

    if (this.baseEncoding == null)
    {
        throw new IllegalArgumentException("Invalid encoding: " + baseEncoding);
    }

    codeToName.putAll(this.baseEncoding.codeToName);
    inverted.putAll(this.baseEncoding.inverted);
    applyDifferences();
}

public void addAttribute(PDAttributeObject attributeObject)
{
    COSName key = COSName.A;
    attributeObject.setStructureElement(this);
    COSBase a = this.getCOSObject().getDictionaryObject(key);
    COSArray array;
    if (a instanceof COSArray)
    {
        array = (COSArray) a;
    }
    else
    {
        array = new COSArray();
        if (a != null)
        {
            array.add(a);
            array.add(COSInteger.get(0));
        }
    }
    this.getCOSObject().setItem(key, array);
    array.add(attributeObject);
    array.add(COSInteger.get(this.getRevisionNumber()));
}

